# Vercel Serverless Zero-Failure Embedded Bundle
EMBEDDED_ASSETS = {'template:about.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>교회소개 & 연혁 | 육군학생군사학교 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n</head>\n<body class="bg-[#faf9f6] text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 헤더 -->\n  <nav class="bg-white/95 backdrop-blur border-b border-gray-200 sticky top-0 z-50">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-20">\n      <a href="/" class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-full bg-[#0f1d38] text-[#f5d77f] flex items-center justify-center text-lg shadow">\n          <i class="fa-solid fa-cross"></i>\n        </div>\n        <div>\n          <span class="text-xs font-semibold text-gray-500 uppercase block">Cadet Military School Church</span>\n          <span class="text-lg font-bold text-[#0f1d38] font-serif-kr">문무대교회 소개</span>\n        </div>\n      </a>\n      <div class="flex items-center gap-4 text-sm font-medium">\n        <a href="/" class="text-gray-600 hover:text-navy-900"><i class="fa-solid fa-house mr-1"></i> 메인으로</a>\n        <a href="/virtual-space" class="text-purple-700 font-semibold text-xs bg-purple-50 px-2.5 py-1 rounded-full border border-purple-200">\n          <i class="fa-solid fa-vr-cardboard mr-1"></i> 3D 가상목양실\n        </a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 서브 히어로 -->\n  <header class="bg-[#0f1d38] text-white py-16 px-4 relative overflow-hidden">\n    <div class="container mx-auto px-4 lg:px-8 relative z-10 max-w-4xl text-center">\n      <span class="px-3 py-1 rounded-full bg-gold-500/20 text-[#f5d77f] text-xs font-semibold border border-gold-500/30 mb-4 inline-block">\n        <i class="fa-solid fa-cross mr-1"></i> 1985년부터 이어져 온 청년 장교 복음화의 요람\n      </span>\n      <h1 class="text-3xl sm:text-5xl font-bold font-serif-kr mb-4">문무대교회 소개 및 연혁</h1>\n      <p class="text-gray-300 text-sm sm:text-base max-w-2xl mx-auto leading-relaxed">\n        대한민국 육군 초급장교의 90% 이상이 거쳐 가는 육군학생군사학교(괴산 문무대) 영내에서<br>\n        구원의 방주이자 군선교의 거룩한 전초기지 역할을 감당하고 있습니다.\n      </p>\n    </div>\n  </header>\n\n  <main class="container mx-auto px-4 lg:px-8 py-12 flex-1 max-w-6xl space-y-16">\n    \n    <!-- 1. 담임목사 인사말 -->\n    <section class="bg-white rounded-3xl p-8 lg:p-12 border border-gray-200 shadow-sm flex flex-col md:flex-row gap-8 items-center">\n      <div class="w-full md:w-1/3">\n        <div class="rounded-2xl overflow-hidden shadow-lg border border-gray-200 aspect-[3/4]">\n          <img src="https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=800&q=80" \n               alt="담임 군종목사 김요한" \n               class="w-full h-full object-cover">\n        </div>\n      </div>\n      <div class="w-full md:w-2/3 space-y-4">\n        <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block">Senior Pastor\'s Message</span>\n        <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr">\n          “청년 장교의 가슴마다 그리스도의 심장을 심겠습니다”\n        </h2>\n        <p class="text-sm text-gray-600 leading-relaxed">\n          할렐루야! 육군학생군사학교 문무대교회 홈페이지를 찾아주신 모든 분들을 주님의 이름으로 축복하고 환영합니다.\n        </p>\n        <p class="text-sm text-gray-600 leading-relaxed">\n          이곳 문무대는 조국의 부름을 받고 전후방 각지의 야전 소대장으로 파송될 수많은 학군사관(ROTC), 학사사관, 군종사관 후보생들이 가장 뜨거운 땀방울을 흘리는 훈련의 현장입니다. 육체적 한계와 두려움에 직면할 때, 우리 후보생들이 예수 그리스도의 십자가 복음을 만나 새 힘을 얻고, 영적 리더십을 갖춘 기독 장교로 일어서도록 섬기는 것이 문무대교회의 거룩한 사명입니다.\n        </p>\n        <p class="text-sm text-gray-600 leading-relaxed">\n          언제나 문무대교회는 문을 활짝 열고 있습니다. 함께 기도해 주시고 후원해 주시는 전국의 모든 교회와 성도님들께 머리 숙여 깊은 감사를 드립니다.\n        </p>\n        <div class="pt-2 flex items-center justify-between border-t border-gray-100">\n          <div>\n            <span class="font-bold text-navy-950 text-base">김요한 군종목사 / 소령(진)</span>\n            <span class="text-xs text-gray-500 block">육군학생군사학교 문무대교회 담임</span>\n          </div>\n          <a href="/virtual-space" class="px-4 py-2 rounded-xl bg-purple-50 text-purple-700 text-xs font-bold hover:bg-purple-100 transition border border-purple-200 flex items-center gap-1.5">\n            <i class="fa-solid fa-cube"></i> 목사님 가상 집무실 방문\n          </a>\n        </div>\n      </div>\n    </section>\n\n    <!-- 2. 섬기는 사람들 (교역자 프로필) -->\n    <section>\n      <div class="text-center max-w-xl mx-auto mb-10">\n        <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block mb-1">Ministers & Staff</span>\n        <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr">섬기는 교역자 소개</h2>\n        <p class="text-xs sm:text-sm text-gray-500 mt-1">장병과 후보생을 위해 눈물과 기도로 헌신하는 문무대교회 사역팀입니다</p>\n      </div>\n\n      <div id="pastors-container" class="grid grid-cols-1 md:grid-cols-3 gap-6">\n        <!-- 동적 로드 또는 기본 렌더링 -->\n      </div>\n    </section>\n\n    <!-- 3. 교회 연혁 타임라인 (사용자 필수 요구사항!) -->\n    <section class="bg-white rounded-3xl p-8 lg:p-12 border border-gray-200 shadow-sm">\n      <div class="text-center max-w-xl mx-auto mb-12">\n        <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block mb-1">History Timeline</span>\n        <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr">문무대교회 40년 연혁</h2>\n        <p class="text-xs sm:text-sm text-gray-500 mt-1">성남에서 괴산까지, 하나님께서 걸어오신 영광의 역사입니다</p>\n      </div>\n\n      <div id="history-timeline" class="relative border-l-2 border-gold-500/40 ml-4 md:ml-32 space-y-10 pl-6 md:pl-8">\n        <!-- 동적 로드 -->\n      </div>\n    </section>\n\n    <!-- 4. 상세 갤러리 (사진첩) -->\n    <section>\n      <div class="flex flex-col md:flex-row md:items-end justify-between mb-8">\n        <div>\n          <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block mb-1">Photo Archive</span>\n          <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr">시설 및 사역 갤러리</h2>\n          <p class="text-xs sm:text-sm text-gray-500 mt-1">사진을 클릭하시면 고화질 원본으로 확대하여 보실 수 있습니다</p>\n        </div>\n      </div>\n\n      <div id="gallery-grid" class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">\n        <!-- 동적 로드 -->\n      </div>\n    </section>\n\n  </main>\n\n  <!-- 라이트박스 모달 -->\n  <div id="lightbox-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay" onclick="closeLightbox()">\n    <div class="relative max-w-4xl max-h-[90vh] bg-black rounded-2xl overflow-hidden shadow-2xl" onclick="event.stopPropagation()">\n      <button onclick="closeLightbox()" class="absolute top-4 right-4 text-white text-2xl z-10 bg-black/50 w-10 h-10 rounded-full flex items-center justify-center">\n        <i class="fa-solid fa-xmark"></i>\n      </button>\n      <img id="lightbox-img" src="" alt="확대 사진" class="max-h-[80vh] w-auto mx-auto object-contain">\n      <div id="lightbox-caption" class="p-4 bg-navy-950 text-white text-xs text-center border-t border-navy-800"></div>\n    </div>\n  </div>\n\n  <footer class="bg-[#0f1d38] text-gray-400 text-xs py-8 text-center border-t border-navy-900 mt-auto">\n    <p>© 2026 육군학생군사학교 문무대교회. 문의 043-830-1004</p>\n  </footer>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    document.addEventListener("DOMContentLoaded", () => {\n      loadPastors();\n      loadHistory();\n      loadGallery();\n    });\n\n    async function loadPastors() {\n      const container = document.getElementById("pastors-container");\n      try {\n        const res = await fetch("/api/pastors");\n        const data = await res.json();\n        container.innerHTML = data.pastors.map(p => `\n          <div class="bg-white rounded-2xl border border-gray-200 overflow-hidden shadow-sm flex flex-col hover:shadow-md transition">\n            <div class="h-60 bg-gray-900 overflow-hidden">\n              <img src="${p.image_url || \'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=600&q=80\'}" \n                   alt="${p.name}" \n                   class="w-full h-full object-cover">\n            </div>\n            <div class="p-6 flex-1 flex flex-col justify-between">\n              <div>\n                <span class="text-xs font-bold text-gold-600 block mb-1">${p.title}</span>\n                <h3 class="text-xl font-bold text-navy-950 mb-2">${p.name}</h3>\n                <p class="text-xs text-gray-500 font-semibold mb-3"><i class="fa-solid fa-briefcase text-gray-400 mr-1"></i> ${p.role}</p>\n                <p class="text-xs text-gray-600 leading-relaxed mb-4">${p.bio}</p>\n              </div>\n              <div class="pt-3 border-t border-gray-100 text-[11px] text-gray-500 italic">\n                <i class="fa-solid fa-quote-left text-gold-400 mr-1"></i> ${p.scripture || \'\'}\n              </div>\n            </div>\n          </div>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    async function loadHistory() {\n      const container = document.getElementById("history-timeline");\n      try {\n        const res = await fetch("/api/history");\n        const data = await res.json();\n        container.innerHTML = data.history.map(item => `\n          <div class="relative group">\n            <span class="absolute -left-[33px] md:-left-[41px] top-1 w-5 h-5 rounded-full bg-white border-4 border-gold-500 shadow"></span>\n            <div class="md:absolute md:-left-32 md:w-24 md:text-right top-0 text-lg font-extrabold text-navy-950 font-serif-kr">\n              ${item.year}\n              <span class="text-xs text-gold-600 block font-normal">${item.month || \'\'}</span>\n            </div>\n            <div class="bg-gray-50 hover:bg-gold-50/30 p-5 rounded-2xl border border-gray-100 transition">\n              <h3 class="font-bold text-navy-950 text-base mb-1">${item.title}</h3>\n              <p class="text-xs text-gray-600 leading-relaxed">${item.description}</p>\n            </div>\n          </div>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    async function loadGallery() {\n      const grid = document.getElementById("gallery-grid");\n      try {\n        const res = await fetch("/api/gallery");\n        const data = await res.json();\n        grid.innerHTML = data.gallery.map(g => `\n          <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-sm bg-gray-900 aspect-[4/3] cursor-pointer" \n               onclick="openLightbox(\'${g.image_url}\', \'${g.title} - ${g.description || \'\'}\')">\n            <img src="${g.image_url}" alt="${g.title}" class="w-full h-full object-cover">\n            <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/20 to-transparent p-5 flex flex-col justify-end text-white">\n              <span class="text-[11px] text-gold-400 font-semibold mb-0.5">${g.category}</span>\n              <h4 class="font-bold text-sm">${g.title}</h4>\n              <p class="text-[11px] text-gray-300 line-clamp-1 mt-0.5">${g.description || \'\'}</p>\n            </div>\n          </div>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    function openLightbox(url, caption) {\n      document.getElementById("lightbox-img").src = url;\n      document.getElementById("lightbox-caption").innerText = caption;\n      document.getElementById("lightbox-modal").classList.remove("hidden");\n    }\n\n    function closeLightbox() {\n      document.getElementById("lightbox-modal").classList.add("hidden");\n    }\n  </script>\n</body>\n</html>\n', 'template:admin.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>군종행정 통합 관리자 포털 | 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n</head>\n<body class="bg-gray-100 text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 1. 로그인 전 화면 -->\n  <div id="login-section" class="flex-1 flex items-center justify-center p-4">\n    <div class="bg-white w-full max-w-md rounded-2xl p-8 border border-gray-200 shadow-xl space-y-6">\n      <div class="text-center">\n        <div class="w-14 h-14 rounded-2xl bg-navy-950 text-gold-400 flex items-center justify-center text-2xl mx-auto mb-3 shadow">\n          <i class="fa-solid fa-lock"></i>\n        </div>\n        <h1 class="text-xl font-bold text-navy-950 font-serif-kr">문무대교회 군종행정 관리자</h1>\n        <p class="text-xs text-gray-500 mt-1">상담, 위문 일정, 엑셀 출력, 콘텐츠 등록 포털</p>\n      </div>\n\n      <form onsubmit="handleLogin(event)" class="space-y-4 text-xs sm:text-sm">\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">관리자 아이디</label>\n          <input type="text" id="admin-id" required value="admin" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-navy-900 outline-none">\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">비밀번호</label>\n          <input type="password" id="admin-pw" required value="munmu1234!" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-navy-900 outline-none">\n          <span class="text-[11px] text-gray-400 mt-1 block">기본 관리자 계정이 자동으로 입력되어 있습니다.</span>\n        </div>\n        <button type="submit" class="w-full py-3 rounded-xl bg-navy-950 text-white font-bold hover:bg-navy-900 transition flex items-center justify-center gap-2">\n          <i class="fa-solid fa-right-to-bracket text-gold-400"></i>\n          <span>대시보드 로그인</span>\n        </button>\n      </form>\n    </div>\n  </div>\n\n  <!-- 2. 로그인 후 메인 대시보드 -->\n  <div id="dashboard-section" class="hidden flex-1 flex flex-col">\n    \n    <header class="bg-navy-950 text-white sticky top-0 z-40 border-b border-navy-800">\n      <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-16">\n        <div class="flex items-center gap-3">\n          <i class="fa-solid fa-cross text-gold-400 text-lg"></i>\n          <span class="font-bold text-sm sm:text-base font-serif-kr">문무대교회 군종행정 포털</span>\n          <span class="text-xs bg-emerald-500/20 text-emerald-300 px-2.5 py-0.5 rounded-full border border-emerald-500/40 flex items-center gap-1">\n            <span class="w-2 h-2 rounded-full bg-emerald-400 animate-ping"></span> 실시간 연동 가동중\n          </span>\n        </div>\n        \n        <div class="flex items-center gap-4 text-xs">\n          <a href="/" target="_blank" class="text-gray-300 hover:text-white transition flex items-center gap-1">\n            <i class="fa-solid fa-arrow-up-right-from-square"></i> 사용자 홈페이지\n          </a>\n          <button onclick="handleLogout()" class="px-3 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-gray-300 transition">\n            <i class="fa-solid fa-arrow-right-from-bracket mr-1"></i> 로그아웃\n          </button>\n        </div>\n      </div>\n    </header>\n\n    <main class="container mx-auto px-4 lg:px-8 py-8 flex-1 max-w-7xl">\n      \n      <!-- 상단 요약 카드 지표 -->\n      <div class="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-8">\n        \n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm flex items-center justify-between">\n          <div>\n            <span class="text-xs text-gray-500 font-semibold block mb-1">목양상담 대기</span>\n            <span class="text-2xl font-extrabold text-navy-950" id="stat-counseling">0</span>\n            <span class="text-xs text-gray-400 block mt-0.5">신규 접수 건수</span>\n          </div>\n          <div class="w-12 h-12 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-xl">\n            <i class="fa-solid fa-comments"></i>\n          </div>\n        </div>\n\n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm flex items-center justify-between">\n          <div>\n            <span class="text-xs text-gray-500 font-semibold block mb-1">위문 신청 심의</span>\n            <span class="text-2xl font-extrabold text-amber-600" id="stat-consolation">0</span>\n            <span class="text-xs text-gray-400 block mt-0.5">검토 대기 중</span>\n          </div>\n          <div class="w-12 h-12 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center text-xl">\n            <i class="fa-solid fa-people-group"></i>\n          </div>\n        </div>\n\n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm flex items-center justify-between">\n          <div>\n            <span class="text-xs text-gray-500 font-semibold block mb-1">후원금 입금 알림</span>\n            <span class="text-2xl font-extrabold text-emerald-600" id="stat-donation">0</span>\n            <span class="text-xs text-gray-400 block mt-0.5" id="stat-donation-amount">0원</span>\n          </div>\n          <div class="w-12 h-12 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center text-xl">\n            <i class="fa-solid fa-coins"></i>\n          </div>\n        </div>\n\n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm flex items-center justify-between">\n          <div>\n            <span class="text-xs text-gray-500 font-semibold block mb-1">행사 총 등록자</span>\n            <span class="text-2xl font-extrabold text-purple-600" id="stat-events">0</span>\n            <span class="text-xs text-gray-400 block mt-0.5">진중세례 및 행사</span>\n          </div>\n          <div class="w-12 h-12 rounded-xl bg-purple-50 text-purple-600 flex items-center justify-center text-xl">\n            <i class="fa-solid fa-water"></i>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- 5대 탭 메뉴 -->\n      <div class="flex border-b border-gray-200 mb-6 space-x-2 overflow-x-auto text-xs sm:text-sm font-bold">\n        <button onclick="switchAdminTab(\'counseling\')" id="atab-counseling" class="px-5 py-3 border-b-2 border-navy-950 text-navy-950 flex items-center gap-1.5 transition">\n          <i class="fa-solid fa-user-doctor text-gold-600"></i> 목양상담 접수 관리\n        </button>\n        <button onclick="switchAdminTab(\'consolation\')" id="atab-consolation" class="px-5 py-3 border-b-2 border-transparent text-gray-500 hover:text-gray-800 flex items-center gap-1.5 transition">\n          <i class="fa-solid fa-calendar-check text-gold-600"></i> 위문 일정 중복 & 승인 관리\n        </button>\n        <button onclick="switchAdminTab(\'donation\')" id="atab-donation" class="px-5 py-3 border-b-2 border-transparent text-gray-500 hover:text-gray-800 flex items-center gap-1.5 transition">\n          <i class="fa-solid fa-bell text-gold-600"></i> 후원금 실시간 입금 확인\n        </button>\n        <button onclick="switchAdminTab(\'events\')" id="atab-events" class="px-5 py-3 border-b-2 border-transparent text-gray-500 hover:text-gray-800 flex items-center gap-1.5 transition">\n          <i class="fa-solid fa-list-check text-gold-600"></i> 행사 참가자 명단 (엑셀)\n        </button>\n        <button onclick="switchAdminTab(\'contents\')" id="atab-contents" class="px-5 py-3 border-b-2 border-transparent text-gray-500 hover:text-gray-800 flex items-center gap-1.5 transition">\n          <i class="fa-solid fa-cloud-arrow-up text-gold-600"></i> 주보 / 설교 / 사진 업로드\n        </button>\n      </div>\n\n      <!-- 탭 1: 목양상담 관리 -->\n      <section id="panel-counseling" class="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">\n        <div class="p-5 border-b border-gray-100 flex justify-between items-center">\n          <div>\n            <h3 class="font-bold text-navy-950 text-base">목양상담 신청 목록</h3>\n            <span class="text-xs text-gray-500">구글 캘린더 자동 연동 및 상태 변경</span>\n          </div>\n        </div>\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-xs">\n            <thead class="bg-gray-50 text-gray-500 uppercase border-b border-gray-200">\n              <tr>\n                <th class="p-3">일시</th>\n                <th class="p-3">신청자</th>\n                <th class="p-3">소속/연락처</th>\n                <th class="p-3">분야</th>\n                <th class="p-3">상담 내용</th>\n                <th class="p-3">상태</th>\n                <th class="p-3">구글 캘린더</th>\n                <th class="p-3">관리</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-counseling" class="divide-y divide-gray-100"></tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 탭 2: 위문 관리 (엑셀 다운로드 지원) -->\n      <section id="panel-consolation" class="hidden bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">\n        <div class="p-5 border-b border-gray-100 flex flex-wrap justify-between items-center gap-3">\n          <div>\n            <h3 class="font-bold text-navy-950 text-base">위문 방문 신청 및 부대 승인 관리</h3>\n            <span class="text-xs text-gray-500">동일 일자 중복 방지 및 출입 차량 관리</span>\n          </div>\n          <button onclick="downloadConsolationsExcel()" class="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl shadow transition flex items-center gap-1.5">\n            <i class="fa-regular fa-file-excel"></i> 위병소 출입 차량명부 엑셀 다운로드\n          </button>\n        </div>\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-xs">\n            <thead class="bg-gray-50 text-gray-500 uppercase border-b border-gray-200">\n              <tr>\n                <th class="p-3">방문 일자/시간</th>\n                <th class="p-3">단체명</th>\n                <th class="p-3">대표자/연락처</th>\n                <th class="p-3">인원</th>\n                <th class="p-3">지원 물품</th>\n                <th class="p-3">차량 번호</th>\n                <th class="p-3">상태</th>\n                <th class="p-3">관리</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-consolation" class="divide-y divide-gray-100"></tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 탭 3: 후원금 관리 -->\n      <section id="panel-donation" class="hidden bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">\n        <div class="p-5 border-b border-gray-100 flex justify-between items-center">\n          <div>\n            <h3 class="font-bold text-navy-950 text-base">후원금 입금 알림 내역</h3>\n            <span class="text-xs text-gray-500">실시간 통보 및 입금 확인 완료 처리</span>\n          </div>\n        </div>\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-xs">\n            <thead class="bg-gray-50 text-gray-500 uppercase border-b border-gray-200">\n              <tr>\n                <th class="p-3">접수 일시</th>\n                <th class="p-3">입금자명</th>\n                <th class="p-3">입금 금액</th>\n                <th class="p-3">입금 은행</th>\n                <th class="p-3">후원 목적</th>\n                <th class="p-3">연락처/메모</th>\n                <th class="p-3">영수증 요청</th>\n                <th class="p-3">상태</th>\n                <th class="p-3">확인</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-donation" class="divide-y divide-gray-100"></tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 탭 4: 행사 참가자 관리 (엑셀 다운로드 지원) -->\n      <section id="panel-events" class="hidden bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">\n        <div class="p-5 border-b border-gray-100 flex flex-wrap justify-between items-center gap-3">\n          <div>\n            <h3 class="font-bold text-navy-950 text-base">행사별 참가 등록자 명단</h3>\n            <span class="text-xs text-gray-500">진중세례 및 특별집회 등록 인원 확인</span>\n          </div>\n          <div class="flex items-center gap-2">\n            <select id="event-select-dropdown" onchange="loadEventAttendees(this.value)" class="px-3 py-2 border rounded-xl text-xs font-bold bg-white">\n              <option value="1">2026 하계 ROTC 후보생 진중세례 및 성찬예배</option>\n              <option value="2">문무대 찬양의 밤 및 청년장교 영성캠프</option>\n              <option value="3">전국 학군단 기독동문회 초청 위문예배</option>\n            </select>\n            <button onclick="downloadEventExcel()" class="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold text-xs rounded-xl shadow transition flex items-center gap-1.5">\n              <i class="fa-regular fa-file-excel"></i> 참가자 명부 엑셀 다운로드\n            </button>\n          </div>\n        </div>\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-xs">\n            <thead class="bg-gray-50 text-gray-500 uppercase border-b border-gray-200">\n              <tr>\n                <th class="p-3">No</th>\n                <th class="p-3">성함</th>\n                <th class="p-3">연락처</th>\n                <th class="p-3">소속</th>\n                <th class="p-3">계급/직분</th>\n                <th class="p-3">동반 인원</th>\n                <th class="p-3">비고/세례여부</th>\n                <th class="p-3">신청일시</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-event-attendees" class="divide-y divide-gray-100"></tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- 탭 5: 콘텐츠 관리 (주보 / 설교 / 사진 업로드) -->\n      <section id="panel-contents" class="hidden space-y-6">\n        \n        <div class="grid grid-cols-1 md:grid-cols-3 gap-6">\n          \n          <!-- 새 주보 등록 카드 -->\n          <div class="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm flex flex-col justify-between">\n            <div>\n              <div class="w-10 h-10 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-lg mb-3">\n                <i class="fa-regular fa-newspaper"></i>\n              </div>\n              <h4 class="font-bold text-navy-950 text-base mb-1">스마트 주보 등록</h4>\n              <p class="text-xs text-gray-500 mb-4">새로운 주차의 주보 이미지 파일을 직접 업로드합니다.</p>\n            </div>\n            <button onclick="openUploadModal(\'bulletin\')" class="w-full py-2.5 rounded-xl bg-navy-900 hover:bg-navy-800 text-white font-bold text-xs transition flex items-center justify-center gap-1.5">\n              <i class="fa-solid fa-plus"></i> 새 주보 업로드\n            </button>\n          </div>\n\n          <!-- 새 설교 영상 등록 카드 -->\n          <div class="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm flex flex-col justify-between">\n            <div>\n              <div class="w-10 h-10 rounded-xl bg-red-50 text-red-600 flex items-center justify-center text-lg mb-3">\n                <i class="fa-brands fa-youtube"></i>\n              </div>\n              <h4 class="font-bold text-navy-950 text-base mb-1">주일 설교 영상 등록</h4>\n              <p class="text-xs text-gray-500 mb-4">유튜브 링크와 성경 본문을 입력하여 메인에 노출합니다.</p>\n            </div>\n            <button onclick="openUploadModal(\'sermon\')" class="w-full py-2.5 rounded-xl bg-navy-900 hover:bg-navy-800 text-white font-bold text-xs transition flex items-center justify-center gap-1.5">\n              <i class="fa-solid fa-plus"></i> 새 설교 등록\n            </button>\n          </div>\n\n          <!-- 갤러리 사진 등록 카드 -->\n          <div class="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm flex flex-col justify-between">\n            <div>\n              <div class="w-10 h-10 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center text-lg mb-3">\n                <i class="fa-regular fa-images"></i>\n              </div>\n              <h4 class="font-bold text-navy-950 text-base mb-1">갤러리 사진 등록</h4>\n              <p class="text-xs text-gray-500 mb-4">진중세례 및 행사 사진을 직접 업로드하여 보관합니다.</p>\n            </div>\n            <button onclick="openUploadModal(\'gallery\')" class="w-full py-2.5 rounded-xl bg-navy-900 hover:bg-navy-800 text-white font-bold text-xs transition flex items-center justify-center gap-1.5">\n              <i class="fa-solid fa-plus"></i> 사진 업로드\n            </button>\n          </div>\n\n        </div>\n\n      </section>\n\n    </main>\n  </div>\n\n  <!-- 주보 등록 모달 -->\n  <div id="modal-bulletin-upload" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-lg rounded-2xl p-6 shadow-2xl space-y-4 text-xs sm:text-sm">\n      <div class="flex justify-between items-center border-b pb-3">\n        <h3 class="font-bold text-base text-navy-950">새 스마트 주보 등록</h3>\n        <button onclick="closeUploadModal(\'bulletin\')" class="text-gray-400 hover:text-gray-700 text-lg"><i class="fa-solid fa-xmark"></i></button>\n      </div>\n      <form onsubmit="submitBulletinForm(event)" class="space-y-3">\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">주보 제목 *</label>\n          <input type="text" id="b-title" required placeholder="예: 2026년 11월 둘째 주일 문무대 주보" class="w-full px-3 py-2 border rounded-xl outline-none">\n        </div>\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">주일 일자 *</label>\n            <input type="date" id="b-date" required class="w-full px-3 py-2 border rounded-xl outline-none">\n          </div>\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">호수 (권호) *</label>\n            <input type="text" id="b-vol" required placeholder="예: 제2026-45호" class="w-full px-3 py-2 border rounded-xl outline-none">\n          </div>\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">주보 이미지 파일 (스마트폰 촬영 또는 스캔본)</label>\n          <input type="file" id="b-file" accept="image/*" class="w-full px-3 py-2 border rounded-xl text-xs">\n        </div>\n        <div class="pt-3 flex justify-end gap-2">\n          <button type="button" onclick="closeUploadModal(\'bulletin\')" class="px-4 py-2 bg-gray-200 rounded-xl font-semibold">취소</button>\n          <button type="submit" class="px-5 py-2 bg-navy-900 text-white rounded-xl font-bold">등록하기</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 설교 등록 모달 -->\n  <div id="modal-sermon-upload" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-lg rounded-2xl p-6 shadow-2xl space-y-4 text-xs sm:text-sm">\n      <div class="flex justify-between items-center border-b pb-3">\n        <h3 class="font-bold text-base text-navy-950">주일 설교 영상 등록</h3>\n        <button onclick="closeUploadModal(\'sermon\')" class="text-gray-400 hover:text-gray-700 text-lg"><i class="fa-solid fa-xmark"></i></button>\n      </div>\n      <form onsubmit="submitSermonForm(event)" class="space-y-3">\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">설교 제목 *</label>\n          <input type="text" id="s-title" required placeholder="예: 강하고 담대하라 두려워하지 말라" class="w-full px-3 py-2 border rounded-xl outline-none">\n        </div>\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">설교자 *</label>\n            <input type="text" id="s-preacher" required value="김요한 군종목사" class="w-full px-3 py-2 border rounded-xl outline-none">\n          </div>\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">선포 일자 *</label>\n            <input type="date" id="s-date" required class="w-full px-3 py-2 border rounded-xl outline-none">\n          </div>\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">성경 본문 *</label>\n          <input type="text" id="s-scripture" required placeholder="예: 여호수아 1장 7-9절" class="w-full px-3 py-2 border rounded-xl outline-none">\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">유튜브 링크 또는 영상 ID *</label>\n          <input type="text" id="s-youtube" required placeholder="예: https://www.youtube.com/watch?v=W5qM9uA_g28" class="w-full px-3 py-2 border rounded-xl outline-none">\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">설교 요약 *</label>\n          <textarea id="s-desc" rows="2" required placeholder="설교의 핵심 메시지를 2~3줄로 요약해 주세요." class="w-full px-3 py-2 border rounded-xl outline-none"></textarea>\n        </div>\n        <div class="pt-3 flex justify-end gap-2">\n          <button type="button" onclick="closeUploadModal(\'sermon\')" class="px-4 py-2 bg-gray-200 rounded-xl font-semibold">취소</button>\n          <button type="submit" class="px-5 py-2 bg-navy-900 text-white rounded-xl font-bold">등록하기</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 갤러리 등록 모달 -->\n  <div id="modal-gallery-upload" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-lg rounded-2xl p-6 shadow-2xl space-y-4 text-xs sm:text-sm">\n      <div class="flex justify-between items-center border-b pb-3">\n        <h3 class="font-bold text-base text-navy-950">갤러리 사진 등록</h3>\n        <button onclick="closeUploadModal(\'gallery\')" class="text-gray-400 hover:text-gray-700 text-lg"><i class="fa-solid fa-xmark"></i></button>\n      </div>\n      <form onsubmit="submitGalleryForm(event)" class="space-y-3">\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">사진 제목 *</label>\n          <input type="text" id="g-title" required placeholder="예: 2026 하계 ROTC 진중세례식 현장" class="w-full px-3 py-2 border rounded-xl outline-none">\n        </div>\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">카테고리 *</label>\n            <select id="g-category" class="w-full px-3 py-2 border rounded-xl outline-none">\n              <option value="진중세례">진중세례</option>\n              <option value="주일예배">주일예배</option>\n              <option value="시설전경">시설전경</option>\n              <option value="위문교제">위문교제</option>\n            </select>\n          </div>\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">촬영 일자</label>\n            <input type="date" id="g-date" class="w-full px-3 py-2 border rounded-xl outline-none">\n          </div>\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">사진 파일 첨부 *</label>\n          <input type="file" id="g-file" accept="image/*" required class="w-full px-3 py-2 border rounded-xl text-xs">\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">간단 설명</label>\n          <input type="text" id="g-desc" placeholder="사진에 대한 설명을 적어주세요." class="w-full px-3 py-2 border rounded-xl outline-none">\n        </div>\n        <div class="pt-3 flex justify-end gap-2">\n          <button type="button" onclick="closeUploadModal(\'gallery\')" class="px-4 py-2 bg-gray-200 rounded-xl font-semibold">취소</button>\n          <button type="submit" class="px-5 py-2 bg-navy-900 text-white rounded-xl font-bold">업로드</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    let isLogged = false;\n    let alertPollTimer = null;\n    let lastAlertCount = 0;\n\n    function handleLogin(e) {\n      e.preventDefault();\n      const id = document.getElementById("admin-id").value;\n      const pw = document.getElementById("admin-pw").value;\n\n      fetch("/api/admin/login", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ username: id, password: pw })\n      })\n      .then(res => res.json())\n      .then(data => {\n        if (data.success) {\n          isLogged = true;\n          document.getElementById("login-section").classList.add("hidden");\n          document.getElementById("dashboard-section").classList.remove("hidden");\n          showToast("관리자 대시보드에 로그인되었습니다.", "success");\n          loadDashboardSummary();\n          loadCounselings();\n          startAlertPolling();\n        } else {\n          showToast(data.detail || "로그인 실패", "error");\n        }\n      })\n      .catch(() => showToast("서버 통신 실패", "error"));\n    }\n\n    function handleLogout() {\n      isLogged = false;\n      if (alertPollTimer) clearInterval(alertPollTimer);\n      document.getElementById("login-section").classList.remove("hidden");\n      document.getElementById("dashboard-section").classList.add("hidden");\n      showToast("로그아웃되었습니다.", "info");\n    }\n\n    function startAlertPolling() {\n      alertPollTimer = setInterval(async () => {\n        try {\n          const res = await fetch("/api/admin/realtime-alerts");\n          const data = await res.json();\n          if (data.alerts && data.alerts.length > lastAlertCount) {\n            const newAlert = data.alerts[0];\n            showToast(`[실시간 알림] ${newAlert.title}`, "success");\n            loadDashboardSummary();\n          }\n          lastAlertCount = data.alerts ? data.alerts.length : 0;\n        } catch (e) {}\n      }, 8000);\n    }\n\n    async function loadDashboardSummary() {\n      try {\n        const res = await fetch("/api/admin/dashboard");\n        const data = await res.json();\n        document.getElementById("stat-counseling").innerText = data.pending_counseling;\n        document.getElementById("stat-consolation").innerText = data.pending_consolations;\n        document.getElementById("stat-donation").innerText = data.pending_donations;\n        document.getElementById("stat-donation-amount").innerText = `${data.pending_donation_amount.toLocaleString()}원`;\n        document.getElementById("stat-events").innerText = data.total_event_registrations;\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    function switchAdminTab(tab) {\n      [\'counseling\', \'consolation\', \'donation\', \'events\', \'contents\'].forEach(t => {\n        const panel = document.getElementById(`panel-${t}`);\n        const btn = document.getElementById(`atab-${t}`);\n        if (t === tab) {\n          panel.classList.remove("hidden");\n          btn.className = "px-5 py-3 border-b-2 border-navy-950 text-navy-950 flex items-center gap-1.5 transition";\n        } else {\n          panel.classList.add("hidden");\n          btn.className = "px-5 py-3 border-b-2 border-transparent text-gray-500 hover:text-gray-800 flex items-center gap-1.5 transition";\n        }\n      });\n\n      if (tab === \'counseling\') loadCounselings();\n      if (tab === \'consolation\') loadConsolations();\n      if (tab === \'donation\') loadDonations();\n      if (tab === \'events\') loadEventAttendees(document.getElementById("event-select-dropdown").value);\n    }\n\n    async function loadCounselings() {\n      const tbody = document.getElementById("tbody-counseling");\n      try {\n        const res = await fetch("/api/admin/counselings");\n        const data = await res.json();\n        tbody.innerHTML = data.counselings.map(item => `\n          <tr class="hover:bg-gray-50">\n            <td class="p-3 font-semibold">${item.date}<br><span class="text-gray-400 text-[11px]">${item.time_slot}</span></td>\n            <td class="p-3 font-bold text-navy-900">${item.name} ${item.is_anonymous ? \'<span class="text-[10px] bg-gray-200 px-1 py-0.5 rounded text-gray-600">익명</span>\' : \'\'}</td>\n            <td class="p-3">${item.phone}<br><span class="text-gray-400 text-[11px]">${item.affiliation || \'-\'}</span></td>\n            <td class="p-3 font-semibold text-blue-700">${item.category}</td>\n            <td class="p-3 max-w-xs truncate" title="${item.message}">${item.message}</td>\n            <td class="p-3 font-bold ${item.status === \'신청완료\' ? \'text-amber-600\' : \'text-emerald-600\'}">${item.status}</td>\n            <td class="p-3">\n              <a href="${item.google_event_link}" target="_blank" class="px-2.5 py-1 rounded bg-blue-50 text-blue-600 hover:bg-blue-100 font-bold text-[11px] inline-flex items-center gap-1">\n                <i class="fa-brands fa-google"></i> 일정 열기\n              </a>\n            </td>\n            <td class="p-3 space-x-1">\n              <button onclick="updateCounselingStatus(${item.id}, \'상담확정\')" class="px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded text-[10px] font-bold">확정</button>\n              <button onclick="updateCounselingStatus(${item.id}, \'상담완료\')" class="px-2 py-1 bg-gray-700 hover:bg-gray-800 text-white rounded text-[10px] font-bold">완료</button>\n            </td>\n          </tr>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    async function updateCounselingStatus(id, status) {\n      const note = prompt("목사님 코멘트 또는 상담 안내 사항을 입력하세요:", status === \'상담확정\' ? "상담이 확정되었습니다. 약속된 시간에 목양실로 방문 바랍니다." : "");\n      if (note === null) return;\n\n      const res = await fetch(`/api/admin/counselings/${id}/status`, {\n        method: "PATCH",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ status: status, admin_notes: note })\n      });\n      const data = await res.json();\n      if (data.success) {\n        showToast("상태가 업데이트되었습니다.", "success");\n        loadCounselings();\n        loadDashboardSummary();\n      }\n    }\n\n    async function loadConsolations() {\n      const tbody = document.getElementById("tbody-consolation");\n      try {\n        const res = await fetch("/api/admin/consolations");\n        const data = await res.json();\n        tbody.innerHTML = data.consolations.map(item => `\n          <tr class="hover:bg-gray-50">\n            <td class="p-3 font-semibold">${item.visit_date}<br><span class="text-gray-400 text-[11px]">${item.visit_time}</span></td>\n            <td class="p-3 font-bold text-navy-900">${item.group_name}</td>\n            <td class="p-3">${item.leader_name} (${item.leader_phone})</td>\n            <td class="p-3 font-bold">${item.num_attendees}명</td>\n            <td class="p-3 max-w-xs truncate" title="${item.items_summary}">${item.items_summary}</td>\n            <td class="p-3 max-w-xs truncate font-mono text-[11px]" title="${item.vehicle_numbers}">${item.vehicle_numbers}</td>\n            <td class="p-3 font-bold ${item.status === \'승인완료\' ? \'text-emerald-600\' : \'text-amber-600\'}">${item.status}</td>\n            <td class="p-3 space-x-1">\n              <button onclick="updateConsolationStatus(${item.id}, \'승인완료\')" class="px-2 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded text-[10px] font-bold">승인</button>\n              <button onclick="updateConsolationStatus(${item.id}, \'일정조율\')" class="px-2 py-1 bg-amber-600 hover:bg-amber-700 text-white rounded text-[10px] font-bold">조율</button>\n              <button onclick="updateConsolationStatus(${item.id}, \'반려\')" class="px-2 py-1 bg-red-600 hover:bg-red-700 text-white rounded text-[10px] font-bold">반려</button>\n            </td>\n          </tr>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    async function updateConsolationStatus(id, status) {\n      const memo = prompt("행정 메모(위병소 통보 사항, 사용 장소 등)를 입력하세요:", status === \'승인완료\' ? "위병소 출입 통보 완료 / 친교실 사용 승인" : "");\n      if (memo === null) return;\n\n      const res = await fetch(`/api/admin/consolations/${id}/status`, {\n        method: "PATCH",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ status: status, admin_notes: memo })\n      });\n      const data = await res.json();\n      if (data.success) {\n        showToast("위문 상태가 업데이트되었습니다.", "success");\n        loadConsolations();\n        loadDashboardSummary();\n      }\n    }\n\n    async function loadDonations() {\n      const tbody = document.getElementById("tbody-donation");\n      try {\n        const res = await fetch("/api/admin/donations");\n        const data = await res.json();\n        tbody.innerHTML = data.donations.map(item => `\n          <tr class="hover:bg-gray-50">\n            <td class="p-3 text-gray-500">${item.created_at}</td>\n            <td class="p-3 font-bold text-navy-900">${item.donor_name}</td>\n            <td class="p-3 font-mono font-bold text-emerald-700">${item.amount.toLocaleString()}원</td>\n            <td class="p-3">${item.bank}</td>\n            <td class="p-3 font-semibold">${item.purpose}</td>\n            <td class="p-3 text-gray-500">${item.phone || \'-\'} / ${item.memo || \'-\'}</td>\n            <td class="p-3">${item.receipt_requested ? \'<span class="text-rose-600 font-bold">요청</span>\' : \'-\'}</td>\n            <td class="p-3 font-bold ${item.status === \'입금확인완료\' ? \'text-emerald-600\' : \'text-amber-600\'}">${item.status}</td>\n            <td class="p-3">\n              ${item.status === \'확인대기\' ? `\n                <button onclick="confirmDonation(${item.id})" class="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded text-[10px] font-bold">확인</button>\n              ` : \'<span class="text-gray-400">완료됨</span>\'}\n            </td>\n          </tr>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    async function confirmDonation(id) {\n      if (!confirm("해당 후원금 입금을 확인 완료 처리하시겠습니까?")) return;\n      const res = await fetch(`/api/admin/donations/${id}/confirm`, { method: "PATCH" });\n      const data = await res.json();\n      if (data.success) {\n        showToast("입금 확인 처리되었습니다.", "success");\n        loadDonations();\n        loadDashboardSummary();\n      }\n    }\n\n    async function loadEventAttendees(eventId) {\n      const tbody = document.getElementById("tbody-event-attendees");\n      try {\n        const res = await fetch(`/api/admin/events/${eventId}/registrations`);\n        const data = await res.json();\n        if (data.registrations.length === 0) {\n          tbody.innerHTML = `<tr><td colspan="8" class="p-6 text-center text-gray-400">해당 행사에 접수된 참가자가 없습니다.</td></tr>`;\n          return;\n        }\n        tbody.innerHTML = data.registrations.map((item, idx) => `\n          <tr class="hover:bg-gray-50">\n            <td class="p-3 text-gray-400 font-mono">${idx + 1}</td>\n            <td class="p-3 font-bold text-navy-900">${item.name}</td>\n            <td class="p-3">${item.phone}</td>\n            <td class="p-3">${item.affiliation || \'-\'}</td>\n            <td class="p-3 font-semibold text-blue-700">${item.rank_or_role || \'-\'}</td>\n            <td class="p-3 font-bold text-emerald-700">+${item.companions_count}명</td>\n            <td class="p-3 text-gray-600">${item.memo || \'-\'}</td>\n            <td class="p-3 text-gray-400">${item.created_at}</td>\n          </tr>\n        `).join(\'\');\n      } catch (e) {\n        console.error(e);\n      }\n    }\n\n    // 엑셀 다운로드 함수들 (스프린트 4)\n    function downloadEventExcel() {\n      const eventId = document.getElementById("event-select-dropdown").value;\n      window.location.href = `/api/admin/events/${eventId}/export-excel`;\n      showToast("행사 참가자 명단 엑셀 다운로드가 시작되었습니다.", "success");\n    }\n\n    function downloadConsolationsExcel() {\n      window.location.href = `/api/admin/consolations/export-excel`;\n      showToast("위문 방문 및 출입차량 명부 엑셀 다운로드가 시작되었습니다.", "success");\n    }\n\n    // 모달 관리\n    function openUploadModal(type) {\n      document.getElementById(`modal-${type}-upload`).classList.remove("hidden");\n    }\n    function closeUploadModal(type) {\n      document.getElementById(`modal-${type}-upload`).classList.add("hidden");\n    }\n\n    // 주보 폼 제출\n    async function submitBulletinForm(e) {\n      e.preventDefault();\n      const fd = new FormData();\n      fd.append("title", document.getElementById("b-title").value);\n      fd.append("date", document.getElementById("b-date").value);\n      fd.append("volume_no", document.getElementById("b-vol").value);\n      const file = document.getElementById("b-file").files[0];\n      if (file) fd.append("image", file);\n\n      const res = await fetch("/api/admin/bulletins", { method: "POST", body: fd });\n      const data = await res.json();\n      if (data.success) {\n        showToast(data.message, "success");\n        closeUploadModal("bulletin");\n      }\n    }\n\n    // 설교 폼 제출\n    async function submitSermonForm(e) {\n      e.preventDefault();\n      const fd = new FormData();\n      fd.append("title", document.getElementById("s-title").value);\n      fd.append("preacher", document.getElementById("s-preacher").value);\n      fd.append("date", document.getElementById("s-date").value);\n      fd.append("scripture", document.getElementById("s-scripture").value);\n      fd.append("youtube_id", document.getElementById("s-youtube").value);\n      fd.append("description", document.getElementById("s-desc").value);\n\n      const res = await fetch("/api/admin/sermons", { method: "POST", body: fd });\n      const data = await res.json();\n      if (data.success) {\n        showToast(data.message, "success");\n        closeUploadModal("sermon");\n      }\n    }\n\n    // 갤러리 폼 제출\n    async function submitGalleryForm(e) {\n      e.preventDefault();\n      const fd = new FormData();\n      fd.append("title", document.getElementById("g-title").value);\n      fd.append("category", document.getElementById("g-category").value);\n      fd.append("date", document.getElementById("g-date").value || "");\n      fd.append("description", document.getElementById("g-desc").value || "");\n      const file = document.getElementById("g-file").files[0];\n      if (file) fd.append("image", file);\n\n      const res = await fetch("/api/admin/gallery", { method: "POST", body: fd });\n      const data = await res.json();\n      if (data.success) {\n        showToast(data.message, "success");\n        closeUploadModal("gallery");\n      }\n    }\n  </script>\n</body>\n</html>\n', 'template:consolation.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>외부 위문 신청 센터 | 육군학생군사학교 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n</head>\n<body class="bg-[#faf9f6] text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 헤더 -->\n  <nav class="bg-white/95 backdrop-blur border-b border-gray-200 sticky top-0 z-50">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-20">\n      <a href="/" class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-full bg-[#0f1d38] text-[#f5d77f] flex items-center justify-center text-lg shadow">\n          <i class="fa-solid fa-cross"></i>\n        </div>\n        <div>\n          <span class="text-xs font-semibold text-gray-500 uppercase block">Cadet Military School Church</span>\n          <span class="text-lg font-bold text-[#0f1d38] font-serif-kr">문무대교회 위문신청센터</span>\n        </div>\n      </a>\n      <div class="flex items-center gap-4 text-sm font-medium">\n        <a href="/" class="text-gray-600 hover:text-navy-900"><i class="fa-solid fa-house mr-1"></i> 메인으로</a>\n        <a href="/admin" class="text-gray-400 hover:text-gray-600 text-xs"><i class="fa-solid fa-lock mr-1"></i>관리자</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 서브 히어로 배너 -->\n  <header class="bg-[#0f1d38] text-white py-14 px-4 relative overflow-hidden">\n    <div class="container mx-auto px-4 lg:px-8 relative z-10 max-w-4xl text-center">\n      <span class="px-3 py-1 rounded-full bg-gold-500/20 text-[#f5d77f] text-xs font-semibold border border-gold-500/30 mb-4 inline-block">\n        <i class="fa-solid fa-calendar-xmark mr-1"></i> 일정 중복 자동 방지 & 부대 출입 연계\n      </span>\n      <h1 class="text-3xl sm:text-4xl font-bold font-serif-kr mb-3">훈련 후보생 위문 방문 신청</h1>\n      <p class="text-gray-300 text-sm max-w-2xl mx-auto leading-relaxed">\n        전국 각지의 후원교회, 기독실업인회, ROTC 총동문회의 사랑에 깊이 감사드립니다.<br>\n        원활한 훈련 일정과 부대 위병소 출입 통제를 위해 <strong>일정 중복 방지 시스템</strong>을 운영합니다.\n      </p>\n    </div>\n  </header>\n\n  <!-- 메인 콘텐트 -->\n  <main class="container mx-auto px-4 lg:px-8 py-10 flex-1 max-w-6xl">\n    \n    <!-- 부대 출입 및 위문 규정 안내 카드 -->\n    <div class="bg-amber-50 border border-amber-200 rounded-2xl p-6 mb-10 flex flex-col md:flex-row gap-6 items-start">\n      <div class="w-12 h-12 rounded-xl bg-amber-500 text-white flex items-center justify-center text-2xl shrink-0">\n        <i class="fa-solid fa-triangle-exclamation"></i>\n      </div>\n      <div class="space-y-2 text-xs sm:text-sm text-gray-700">\n        <h3 class="font-bold text-gray-900 text-base">위문 단체 방문 수칙 및 사전 협의 안내</h3>\n        <p>• <strong>일정 중복 방지:</strong> 후보생들의 주일 정규 훈련 및 영성 집회 진행을 위해 <strong>동일 시간대에는 1개 단체의 위문만 승인</strong>됩니다.</p>\n        <p>• <strong>위병소 보안 출입:</strong> 방문 신청 시 기재하신 차량번호와 탑승 인원은 군사보호구역 출입 승인 자료로 사용되므로 정확히 입력해 주십시오.</p>\n        <p>• <strong>간식류 반입 규정:</strong> 단체 급식 안전을 위해 제조일자 및 유통기한이 명시된 완제품 위주로 반입이 허용됩니다 (김밥/회 등 부패 위험식품 반입 제한).</p>\n      </div>\n    </div>\n\n    <div class="grid grid-cols-1 lg:grid-cols-12 gap-8">\n      \n      <!-- 좌측: 현재 확정된 위문 일정 (중복 방지 현황판) -->\n      <div class="lg:col-span-5 bg-white p-6 rounded-2xl border border-gray-200 shadow-sm flex flex-col">\n        <div class="flex items-center justify-between mb-4 pb-3 border-b border-gray-100">\n          <h2 class="font-bold text-[#0f1d38] text-base flex items-center gap-2">\n            <i class="fa-regular fa-calendar-days text-gold-600"></i>\n            <span>확정된 위문 일정 현황</span>\n          </h2>\n          <span class="text-xs bg-red-50 text-red-700 px-2 py-0.5 rounded font-medium">해당일 중복 신청 불가</span>\n        </div>\n        <p class="text-xs text-gray-500 mb-4">아래 기재된 일자는 이미 위문 일정이 확정되었으므로 다른 날짜를 선택해 주십시오.</p>\n\n        <div id="booked-schedule-list" class="space-y-3 overflow-y-auto max-h-[440px] pr-1">\n          <div class="text-center py-10 text-gray-400 text-xs">\n            <i class="fa-solid fa-spinner fa-spin text-lg mb-2"></i><br>\n            일정을 불러오는 중입니다...\n          </div>\n        </div>\n\n        <div class="mt-auto pt-4 border-t border-gray-100 text-[11px] text-gray-400">\n          <i class="fa-solid fa-phone mr-1"></i> 일정 조율 문의: 군종실 043-830-1004\n        </div>\n      </div>\n\n      <!-- 우측: 위문 신청서 작성 폼 -->\n      <div class="lg:col-span-7 bg-white p-6 sm:p-8 rounded-2xl border border-gray-200 shadow-sm">\n        <h2 class="font-bold text-[#0f1d38] text-base mb-1 flex items-center gap-2">\n          <i class="fa-solid fa-file-signature text-gold-600"></i>\n          <span>위문 신청서 접수</span>\n        </h2>\n        <p class="text-xs text-gray-500 mb-6">부대 심의 후 군종실에서 담당자께 승인 결과를 안내해 드립니다.</p>\n\n        <form id="consolation-form" onsubmit="submitConsolation(event)" class="space-y-4 text-xs sm:text-sm">\n          \n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">방문 희망 일자 *</label>\n              <input type="date" id="c-date" required onchange="checkDateConflict(this.value)" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n              <span id="date-warning" class="hidden text-xs text-rose-600 font-bold mt-1 block"></span>\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">방문 희망 시간대 *</label>\n              <select id="c-time" required class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none font-medium">\n                <option value="오전 10:00 - 13:00 (주일 2부 예배 연계)">오전 10:00 - 13:00 (주일 2부 예배 연계)</option>\n                <option value="오후 13:00 - 16:00 (오후 위문 및 교제)">오후 13:00 - 16:00 (오후 위문 및 교제)</option>\n                <option value="평일 저녁 18:30 - 20:30 (수요/금요 집회)">평일 저녁 18:30 - 20:30 (수요/금요 집회)</option>\n              </select>\n            </div>\n          </div>\n\n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">신청 교회 / 단체명 *</label>\n              <input type="text" id="c-group" required placeholder="예: 서울 온누리교회 대학청년부" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">예상 방문 인원수 (명) *</label>\n              <input type="number" id="c-attendees" required min="1" max="200" placeholder="예: 25" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n          </div>\n\n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">대표자 / 인솔자 성함 *</label>\n              <input type="text" id="c-leader" required placeholder="예: 박준형 목사 / 총무" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">대표자 연락처 *</label>\n              <input type="tel" id="c-leader-phone" required placeholder="010-0000-0000" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">대표자 이메일 (승인서 수신용)</label>\n            <input type="email" id="c-leader-email" placeholder="leader@example.com" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">후보생 지원 물품 내역 *</label>\n            <input type="text" id="c-items" required placeholder="예: 햄버거 세트 400개, 보온 텀블러, 청년 도서 등" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">부대 출입 차량번호 목록 (위병소 보안 등록용) *</label>\n            <textarea id="c-vehicles" required rows="2" placeholder="예: 대형버스 1대 (12가3456), 승용차 2대 (34나5678, 90다1234)" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none"></textarea>\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">방문 목적 및 요청 사항</label>\n            <textarea id="c-purpose" rows="2" placeholder="예: 하계 입영훈련 후보생 격려 및 주일 2부 연합예배 특송 참여 희망" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none"></textarea>\n          </div>\n\n          <button type="submit" id="btn-submit-consolation" class="w-full py-3.5 rounded-xl bg-[#0f1d38] hover:bg-[#1a2f57] text-white font-bold shadow-lg transition flex items-center justify-center gap-2 text-sm sm:text-base">\n            <i class="fa-solid fa-paper-plane text-gold-400"></i>\n            <span>위문 신청서 제출하기</span>\n          </button>\n        </form>\n      </div>\n\n    </div>\n\n  </main>\n\n  <footer class="bg-[#0f1d38] text-gray-400 text-xs py-8 text-center border-t border-navy-900 mt-auto">\n    <p>© 2026 육군학생군사학교 문무대교회 군종실. 문의 043-830-1004</p>\n  </footer>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    let bookedDates = [];\n\n    document.addEventListener("DOMContentLoaded", () => {\n      // 날짜 선택 최소값을 내일로 설정\n      const tomorrow = new Date();\n      tomorrow.setDate(tomorrow.getDate() + 1);\n      document.getElementById("c-date").min = tomorrow.toISOString().split("T")[0];\n\n      loadBookedSchedules();\n    });\n\n    async function loadBookedSchedules() {\n      const list = document.getElementById("booked-schedule-list");\n      try {\n        const res = await fetch("/api/consolations/booked-dates");\n        const data = await res.json();\n        bookedDates = data.booked_schedules;\n\n        if (!bookedDates || bookedDates.length === 0) {\n          list.innerHTML = `<div class="p-6 text-center text-gray-400 text-xs">현재 등록된 위문 일정이 없습니다. 원하시는 날짜로 자유롭게 신청 가능합니다.</div>`;\n          return;\n        }\n\n        list.innerHTML = bookedDates.map(item => `\n          <div class="p-3 rounded-xl border ${item.status === \'승인완료\' ? \'border-red-200 bg-red-50/50\' : \'border-amber-200 bg-amber-50/40\'} text-xs">\n            <div class="flex justify-between items-center mb-1">\n              <span class="font-bold text-gray-900 flex items-center gap-1.5">\n                <i class="fa-regular fa-calendar-check text-red-600"></i> ${item.visit_date}\n              </span>\n              <span class="px-2 py-0.5 rounded text-[10px] font-bold ${item.status === \'승인완료\' ? \'bg-red-100 text-red-800\' : \'bg-amber-100 text-amber-800\'}">\n                ${item.status === \'승인완료\' ? \'확정 (마감)\' : \'심의중\'}\n              </span>\n            </div>\n            <div class="text-gray-700 font-semibold">${item.group_name}</div>\n            <div class="text-gray-500 text-[11px] mt-0.5"><i class="fa-regular fa-clock mr-1"></i> ${item.visit_time}</div>\n          </div>\n        `).join(\'\');\n\n      } catch (err) {\n        list.innerHTML = `<div class="p-4 text-center text-red-500 text-xs">일정을 불러오는 중 오류가 발생했습니다.</div>`;\n      }\n    }\n\n    function checkDateConflict(selectedDate) {\n      const warning = document.getElementById("date-warning");\n      const btn = document.getElementById("btn-submit-consolation");\n\n      const conflict = bookedDates.find(b => b.visit_date === selectedDate && b.status === \'승인완료\');\n      if (conflict) {\n        warning.innerText = `선택하신 일자(${selectedDate})는 이미 [${conflict.group_name}]의 위문 일정이 확정되어 있습니다. 다른 날짜를 선택해 주세요.`;\n        warning.classList.remove("hidden");\n        btn.disabled = true;\n        btn.classList.add("opacity-50", "cursor-not-allowed");\n      } else {\n        warning.classList.add("hidden");\n        btn.disabled = false;\n        btn.classList.remove("opacity-50", "cursor-not-allowed");\n      }\n    }\n\n    async function submitConsolation(e) {\n      e.preventDefault();\n      const payload = {\n        visit_date: document.getElementById("c-date").value,\n        visit_time: document.getElementById("c-time").value,\n        group_name: document.getElementById("c-group").value,\n        num_attendees: parseInt(document.getElementById("c-attendees").value, 10),\n        leader_name: document.getElementById("c-leader").value,\n        leader_phone: document.getElementById("c-leader-phone").value,\n        leader_email: document.getElementById("c-leader-email").value || null,\n        items_summary: document.getElementById("c-items").value,\n        vehicle_numbers: document.getElementById("c-vehicles").value,\n        purpose: document.getElementById("c-purpose").value || null\n      };\n\n      try {\n        const res = await fetch("/api/consolations/request", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (res.ok && data.success) {\n          showToast(data.message, "success");\n          document.getElementById("consolation-form").reset();\n          loadBookedSchedules();\n        } else {\n          showToast(data.detail || "오류가 발생했습니다.", "error");\n        }\n      } catch (err) {\n        showToast("서버와 통신할 수 없습니다.", "error");\n      }\n    }\n  </script>\n</body>\n</html>\n', 'template:counseling.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>목양상담 센터 | 육군학생군사학교 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n</head>\n<body class="bg-[#faf9f6] text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 헤더 네비게이션 -->\n  <nav class="bg-white/95 backdrop-blur border-b border-gray-200 sticky top-0 z-50">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-20">\n      <a href="/" class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-full bg-[#0f1d38] text-[#f5d77f] flex items-center justify-center text-lg shadow">\n          <i class="fa-solid fa-cross"></i>\n        </div>\n        <div>\n          <span class="text-xs font-semibold text-gray-500 uppercase block">Cadet Military School Church</span>\n          <span class="text-lg font-bold text-[#0f1d38] font-serif-kr">문무대교회 목양상담센터</span>\n        </div>\n      </a>\n      <div class="flex items-center gap-4 text-sm font-medium">\n        <a href="/" class="text-gray-600 hover:text-navy-900"><i class="fa-solid fa-house mr-1"></i> 메인으로</a>\n        <a href="/admin" class="text-gray-400 hover:text-gray-600 text-xs"><i class="fa-solid fa-lock mr-1"></i>관리자</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 서브 히어로 배너 -->\n  <header class="bg-[#0f1d38] text-white py-14 px-4 relative overflow-hidden">\n    <div class="container mx-auto px-4 lg:px-8 relative z-10 max-w-4xl text-center">\n      <span class="px-3 py-1 rounded-full bg-gold-500/20 text-[#f5d77f] text-xs font-semibold border border-gold-500/30 mb-4 inline-block">\n        <i class="fa-solid fa-shield-heart mr-1"></i> 철저한 비밀보장 & 영적 돌봄\n      </span>\n      <h1 class="text-3xl sm:text-4xl font-bold font-serif-kr mb-3">군종목사 1:1 목양상담 신청</h1>\n      <p class="text-gray-300 text-sm max-w-2xl mx-auto leading-relaxed">\n        고된 훈련과 군 복무 중 겪는 신앙, 진로, 대인관계의 고민을 주님의 사랑으로 함께 나눕니다.<br>\n        목사님이 오픈해 둔 시간대를 선택하시면 확정 후 <strong>구글 캘린더에 자동으로 연동</strong>됩니다.\n      </p>\n    </div>\n  </header>\n\n  <!-- 메인 콘텐츠 영역 (탭: 상담 신청 / 내 상담 조회) -->\n  <main class="container mx-auto px-4 lg:px-8 py-10 flex-1 max-w-5xl">\n    \n    <!-- 상단 탭 버튼 -->\n    <div class="flex justify-center mb-8">\n      <div class="inline-flex bg-gray-200 p-1.5 rounded-2xl shadow-inner">\n        <button id="tab-btn-apply" onclick="switchTab(\'apply\')" class="px-6 py-2.5 rounded-xl font-bold text-sm bg-white text-[#0f1d38] shadow transition">\n          <i class="fa-regular fa-calendar-plus mr-1.5 text-gold-600"></i> 새로운 상담 신청\n        </button>\n        <button id="tab-btn-check" onclick="switchTab(\'check\')" class="px-6 py-2.5 rounded-xl font-semibold text-sm text-gray-600 hover:text-gray-900 transition">\n          <i class="fa-solid fa-key mr-1.5"></i> 내 비밀상담 상태 조회\n        </button>\n      </div>\n    </div>\n\n    <!-- 1. 상담 신청 섹션 -->\n    <section id="tab-content-apply" class="grid grid-cols-1 lg:grid-cols-12 gap-8">\n      \n      <!-- 좌측: 시간 슬롯 선택 -->\n      <div class="lg:col-span-5 bg-white p-6 rounded-2xl border border-gray-200 shadow-sm flex flex-col">\n        <div class="flex items-center justify-between mb-4 pb-3 border-b border-gray-100">\n          <h2 class="font-bold text-[#0f1d38] text-base flex items-center gap-2">\n            <i class="fa-regular fa-clock text-gold-600"></i>\n            <span>상담 가능 일자 및 시간 선택</span>\n          </h2>\n          <span class="text-xs bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded font-medium">실시간 예약 가능</span>\n        </div>\n        <p class="text-xs text-gray-500 mb-4">원하시는 날짜와 시간대를 클릭하여 선택해 주세요.</p>\n\n        <!-- 슬롯 컨테이너 -->\n        <div id="slots-container" class="space-y-3 overflow-y-auto max-h-[460px] pr-1">\n          <div class="text-center py-10 text-gray-400 text-xs">\n            <i class="fa-solid fa-spinner fa-spin text-lg mb-2"></i><br>\n            상담 가능 일정을 불러오는 중입니다...\n          </div>\n        </div>\n\n        <div class="mt-4 pt-3 border-t border-gray-100 text-[11px] text-gray-400">\n          <i class="fa-solid fa-circle-info mr-1"></i> 예약된 시간대는 자동으로 구글 캘린더 등록 링크가 발급됩니다.\n        </div>\n      </div>\n\n      <!-- 우측: 신청 폼 -->\n      <div class="lg:col-span-7 bg-white p-6 sm:p-8 rounded-2xl border border-gray-200 shadow-sm">\n        <h2 class="font-bold text-[#0f1d38] text-base mb-1 flex items-center gap-2">\n          <i class="fa-solid fa-pen-to-square text-gold-600"></i>\n          <span>상담 신청서 작성</span>\n        </h2>\n        <p class="text-xs text-gray-500 mb-6">선택하신 시간대에 맞춰 정성껏 준비하겠습니다.</p>\n\n        <form id="counseling-form" onsubmit="submitCounseling(event)" class="space-y-4 text-xs sm:text-sm">\n          \n          <!-- 선택된 일자 배지 -->\n          <div class="p-3 bg-blue-50 border border-blue-200 rounded-xl flex items-center justify-between">\n            <div class="flex items-center gap-2">\n              <i class="fa-solid fa-calendar-check text-blue-600 text-base"></i>\n              <div>\n                <span class="text-[11px] text-blue-600 font-bold block">선택된 상담 시간</span>\n                <span id="selected-slot-display" class="font-bold text-gray-900 text-xs sm:text-sm">좌측에서 시간대를 먼저 선택해주세요</span>\n              </div>\n            </div>\n            <input type="hidden" id="slot-id">\n            <input type="hidden" id="slot-date">\n            <input type="hidden" id="slot-time">\n          </div>\n\n          <!-- 인적사항 -->\n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">성함 (또는 닉네임) *</label>\n              <input type="text" id="c-name" required placeholder="예: 홍길동 후보생" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">연락처 (휴대폰) *</label>\n              <input type="tel" id="c-phone" required placeholder="010-0000-0000" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n          </div>\n\n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">소속 / 교육대대</label>\n              <input type="text" id="c-affiliation" placeholder="예: 학군 64기 2대대 3중대 / 기간병" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">상담 분야 *</label>\n              <select id="c-category" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none font-medium">\n                <option value="신앙/영적 고민">신앙 및 영적 성장</option>\n                <option value="군 복무 및 훈련 적응">군 복무 및 훈련 고충 적응</option>\n                <option value="진로 및 미래">진로, 임관 및 미래 설계</option>\n                <option value="대인관계 및 가정">전우·이성·가족 대인관계</option>\n                <option value="기타 고충">기타 심리적 고충 상담</option>\n              </select>\n            </div>\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">이메일 (구글 캘린더 초대장 수신용)</label>\n            <input type="email" id="c-email" placeholder="example@gmail.com" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">나누고 싶은 내용 또는 기도제목 *</label>\n            <textarea id="c-message" required rows="4" placeholder="상담받고 싶은 내용을 간단히 적어주시면 목사님께서 기도로 준비하시는 데 큰 도움이 됩니다." class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none"></textarea>\n          </div>\n\n          <!-- 비밀보장 모드 옵션 -->\n          <div class="p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-3">\n            <div class="flex items-center justify-between">\n              <div class="flex items-center gap-2">\n                <input type="checkbox" id="c-anonymous" onchange="toggleSecretCode(this.checked)" class="rounded w-4 h-4 text-[#0f1d38]">\n                <label for="c-anonymous" class="font-bold text-gray-800 text-xs sm:text-sm cursor-pointer">\n                  비밀보장 모드 (익명 & 비밀번호 설정)\n                </label>\n              </div>\n              <span class="text-[11px] text-gray-500">군내 신분 비공개 희망 시</span>\n            </div>\n\n            <div id="secret-code-box" class="hidden pt-2 border-t border-gray-200">\n              <label class="block font-bold text-gray-700 mb-1 text-xs">본인 확인용 4자리 비밀코드 *</label>\n              <input type="password" id="c-secret" maxlength="6" placeholder="숫자 4~6자리 입력" class="w-48 px-3 py-2 border rounded-lg focus:outline-none focus:border-[#0f1d38]">\n              <p class="text-[11px] text-gray-500 mt-1">상담 현황 및 목사님 코멘트를 조회할 때 사용됩니다.</p>\n            </div>\n          </div>\n\n          <button type="submit" class="w-full py-3.5 rounded-xl bg-[#0f1d38] hover:bg-[#1a2f57] text-white font-bold shadow-lg transition flex items-center justify-center gap-2 text-sm sm:text-base">\n            <i class="fa-solid fa-paper-plane text-gold-400"></i>\n            <span>상담 신청 완료하기</span>\n          </button>\n        </form>\n      </div>\n    </section>\n\n    <!-- 2. 비밀상담 상태 조회 섹션 -->\n    <section id="tab-content-check" class="hidden max-w-xl mx-auto bg-white p-8 rounded-2xl border border-gray-200 shadow-sm">\n      <div class="text-center mb-6">\n        <div class="w-12 h-12 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center text-xl mx-auto mb-2">\n          <i class="fa-solid fa-lock"></i>\n        </div>\n        <h2 class="text-xl font-bold text-[#0f1d38] font-serif-kr">내 비밀상담 상태 조회</h2>\n        <p class="text-xs text-gray-500 mt-1">신청 시 입력하신 이름과 4자리 비밀코드를 입력해 주세요.</p>\n      </div>\n\n      <form onsubmit="checkMyCounseling(event)" class="space-y-4 text-xs sm:text-sm">\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">신청자 성함 / 닉네임 *</label>\n          <input type="text" id="check-name" required placeholder="신청 시 입력한 이름" class="w-full px-3 py-2.5 border rounded-xl outline-none focus:ring-2 focus:ring-[#0f1d38]">\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">비밀코드 (4~6자리) *</label>\n          <input type="password" id="check-code" required placeholder="비밀번호" class="w-full px-3 py-2.5 border rounded-xl outline-none focus:ring-2 focus:ring-[#0f1d38]">\n        </div>\n        <button type="submit" class="w-full py-3 rounded-xl bg-navy-900 text-white font-bold hover:bg-navy-800 transition">\n          상담 결과 조회\n        </button>\n      </form>\n\n      <!-- 조회 결과 카드 -->\n      <div id="check-result" class="hidden mt-6 p-5 rounded-xl bg-gray-50 border border-gray-200 space-y-3 text-xs">\n        <div class="flex justify-between items-center border-b pb-2">\n          <span class="font-bold text-gray-800 text-sm" id="res-name">홍길동 후보생</span>\n          <span id="res-status" class="px-2 py-0.5 rounded font-bold text-xs bg-blue-100 text-blue-800">신청완료</span>\n        </div>\n        <div>\n          <span class="text-gray-500 block">상담 일시</span>\n          <span class="font-bold text-gray-900" id="res-datetime">2026-11-10 14:00 - 15:00</span>\n        </div>\n        <div>\n          <span class="text-gray-500 block">군종목사 안내 코멘트</span>\n          <p class="p-3 bg-white rounded-lg border text-gray-700 mt-1 leading-relaxed" id="res-notes">\n            아직 담당 목사님의 코멘트가 등록되지 않았습니다. 잠시 후 확인해 주세요.\n          </p>\n        </div>\n      </div>\n    </section>\n\n  </main>\n\n  <!-- 신청 성공 & 구글 캘린더 등록 모달 -->\n  <div id="success-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-md rounded-2xl overflow-hidden shadow-2xl p-6 text-center space-y-4">\n      <div class="w-16 h-16 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-3xl mx-auto">\n        <i class="fa-solid fa-circle-check"></i>\n      </div>\n      \n      <h3 class="text-xl font-bold text-navy-950 font-serif-kr">목양상담 예약이 접수되었습니다</h3>\n      <p class="text-xs text-gray-600 leading-relaxed">\n        선택하신 상담 일정이 안전하게 등록되었습니다.<br>\n        아래 버튼을 눌러 본인의 <strong>구글 캘린더</strong>에 일정을 저장해 두세요!\n      </p>\n\n      <div class="p-3 bg-gray-50 rounded-xl border text-left text-xs space-y-1">\n        <div><strong>일시:</strong> <span id="modal-datetime">2026-11-10 (14:00 - 15:00)</span></div>\n        <div><strong>장소:</strong> 문무대교회 2층 목양실</div>\n        <div><strong>담당:</strong> 김요한 군종목사</div>\n      </div>\n\n      <div class="space-y-2 pt-2">\n        <a id="btn-google-cal" href="#" target="_blank" class="w-full py-3 rounded-xl bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs flex items-center justify-center gap-2 shadow transition">\n          <i class="fa-brands fa-google"></i>\n          <span>구글 캘린더에 일정 자동 등록하기</span>\n        </a>\n        <button id="btn-ics-download" class="w-full py-2.5 rounded-xl bg-gray-100 hover:bg-gray-200 text-gray-700 font-semibold text-xs flex items-center justify-center gap-2 transition">\n          <i class="fa-regular fa-calendar-arrow-down"></i>\n          <span>아이폰 / 캘린더 파일(.ics) 다운로드</span>\n        </button>\n      </div>\n\n      <button onclick="closeSuccessModal()" class="w-full py-2 text-xs text-gray-500 hover:text-gray-800 transition">\n        확인하고 닫기\n      </button>\n    </div>\n  </div>\n\n  <footer class="bg-[#0f1d38] text-gray-400 text-xs py-8 text-center border-t border-navy-900 mt-auto">\n    <p>© 2026 육군학생군사학교 문무대교회 목양실. 문의 043-830-1004</p>\n  </footer>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    let currentSlots = [];\n    let selectedSlot = null;\n\n    document.addEventListener("DOMContentLoaded", () => {\n      loadSlots();\n    });\n\n    function switchTab(tab) {\n      const applyTab = document.getElementById("tab-content-apply");\n      const checkTab = document.getElementById("tab-content-check");\n      const btnApply = document.getElementById("tab-btn-apply");\n      const btnCheck = document.getElementById("tab-btn-check");\n\n      if (tab === \'apply\') {\n        applyTab.classList.remove("hidden");\n        checkTab.classList.add("hidden");\n        btnApply.className = "px-6 py-2.5 rounded-xl font-bold text-sm bg-white text-[#0f1d38] shadow transition";\n        btnCheck.className = "px-6 py-2.5 rounded-xl font-semibold text-sm text-gray-600 hover:text-gray-900 transition";\n      } else {\n        applyTab.classList.add("hidden");\n        checkTab.classList.remove("hidden");\n        btnCheck.className = "px-6 py-2.5 rounded-xl font-bold text-sm bg-white text-[#0f1d38] shadow transition";\n        btnApply.className = "px-6 py-2.5 rounded-xl font-semibold text-sm text-gray-600 hover:text-gray-900 transition";\n      }\n    }\n\n    function toggleSecretCode(checked) {\n      const box = document.getElementById("secret-code-box");\n      if (checked) {\n        box.classList.remove("hidden");\n      } else {\n        box.classList.add("hidden");\n      }\n    }\n\n    async function loadSlots() {\n      const container = document.getElementById("slots-container");\n      try {\n        const res = await fetch("/api/counseling/slots");\n        const data = await res.json();\n        currentSlots = data.slots;\n\n        if (!currentSlots || currentSlots.length === 0) {\n          container.innerHTML = `<div class="p-4 text-center text-gray-400 text-xs">현재 예약 가능한 상담 슬롯이 없습니다. 군종실로 직접 연락 바랍니다.</div>`;\n          return;\n        }\n\n        // 날짜별 그룹화\n        const grouped = {};\n        currentSlots.forEach(s => {\n          if (!grouped[s.date]) grouped[s.date] = [];\n          grouped[s.date].push(s);\n        });\n\n        let html = \'\';\n        for (const date in grouped) {\n          const slots = grouped[date];\n          html += `\n            <div class="mb-4">\n              <div class="text-xs font-bold text-gray-700 mb-2 flex items-center gap-1.5">\n                <i class="fa-regular fa-calendar text-gold-600"></i> ${date}\n              </div>\n              <div class="grid grid-cols-2 gap-2">\n                ${slots.map(slot => `\n                  <button type="button" \n                          onclick="selectSlot(${slot.id}, \'${slot.date}\', \'${slot.time_slot}\')" \n                          class="slot-btn text-left p-2.5 rounded-xl border border-gray-200 hover:border-gold-500 hover:bg-gold-50/40 text-xs transition flex flex-col justify-between"\n                          id="slot-btn-${slot.id}">\n                    <span class="font-bold text-gray-800">${slot.time_slot}</span>\n                    <span class="text-[10px] text-emerald-600 mt-1">예약 가능</span>\n                  </button>\n                `).join(\'\')}\n              </div>\n            </div>\n          `;\n        }\n        container.innerHTML = html;\n\n        // 첫 번째 슬롯 자동 선택\n        if (currentSlots.length > 0) {\n          selectSlot(currentSlots[0].id, currentSlots[0].date, currentSlots[0].time_slot);\n        }\n\n      } catch (err) {\n        container.innerHTML = `<div class="p-4 text-center text-red-500 text-xs">일정을 불러오는 중 오류가 발생했습니다.</div>`;\n      }\n    }\n\n    function selectSlot(id, date, timeSlot) {\n      selectedSlot = { id, date, timeSlot };\n      document.getElementById("slot-id").value = id;\n      document.getElementById("slot-date").value = date;\n      document.getElementById("slot-time").value = timeSlot;\n      document.getElementById("selected-slot-display").innerText = `${date} (${timeSlot})`;\n\n      // 스타일 활성화 표시\n      document.querySelectorAll(".slot-btn").forEach(b => {\n        b.classList.remove("border-gold-600", "bg-gold-100", "ring-2", "ring-gold-500");\n      });\n      const activeBtn = document.getElementById(`slot-btn-${id}`);\n      if (activeBtn) {\n        activeBtn.classList.add("border-gold-600", "bg-gold-100", "ring-2", "ring-gold-500");\n      }\n    }\n\n    async function submitCounseling(e) {\n      e.preventDefault();\n      if (!selectedSlot) {\n        showToast("상담 일시를 먼저 선택해 주세요.", "error");\n        return;\n      }\n\n      const isAnonymous = document.getElementById("c-anonymous").checked;\n      const secretCode = document.getElementById("c-secret").value;\n      if (isAnonymous && !secretCode) {\n        showToast("비밀보장 모드를 위한 4자리 비밀코드를 입력해 주세요.", "error");\n        return;\n      }\n\n      const payload = {\n        slot_id: selectedSlot.id,\n        date: selectedSlot.date,\n        time_slot: selectedSlot.timeSlot,\n        name: document.getElementById("c-name").value,\n        phone: document.getElementById("c-phone").value,\n        email: document.getElementById("c-email").value || null,\n        affiliation: document.getElementById("c-affiliation").value || null,\n        category: document.getElementById("c-category").value,\n        message: document.getElementById("c-message").value,\n        is_anonymous: isAnonymous,\n        secret_code: secretCode || null\n      };\n\n      try {\n        const res = await fetch("/api/counseling/request", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (data.success) {\n          showToast("상담이 성공적으로 신청되었습니다!", "success");\n          \n          // 구글 캘린더 링크 설정\n          document.getElementById("btn-google-cal").href = data.google_calendar_url;\n          document.getElementById("modal-datetime").innerText = `${data.date} (${data.time_slot})`;\n          \n          // ics 다운로드 핸들러 바인딩\n          document.getElementById("btn-ics-download").onclick = () => {\n            downloadIcsFile("[문무대교회 목양상담] 군종목사 1:1 상담", data.date, data.time_slot, payload.message);\n          };\n\n          document.getElementById("success-modal").classList.remove("hidden");\n          document.getElementById("counseling-form").reset();\n          loadSlots(); // 슬롯 갱신\n        } else {\n          showToast(data.detail || "오류가 발생했습니다.", "error");\n        }\n      } catch (err) {\n        showToast("서버와 통신할 수 없습니다.", "error");\n      }\n    }\n\n    function closeSuccessModal() {\n      document.getElementById("success-modal").classList.add("hidden");\n    }\n\n    async function checkMyCounseling(e) {\n      e.preventDefault();\n      const name = document.getElementById("check-name").value;\n      const code = document.getElementById("check-code").value;\n\n      try {\n        const res = await fetch("/api/counseling/check", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify({ name, secret_code: code })\n        });\n        const data = await res.json();\n        if (res.ok) {\n          const item = data.counseling;\n          document.getElementById("res-name").innerText = `${item.name} (${item.category})`;\n          document.getElementById("res-status").innerText = item.status;\n          document.getElementById("res-datetime").innerText = `${item.date} ${item.time_slot}`;\n          document.getElementById("res-notes").innerText = item.admin_notes || "아직 목사님의 코멘트가 등록되지 않았습니다. 예약 일시에 맞춰 목양실로 오시면 됩니다.";\n          document.getElementById("check-result").classList.remove("hidden");\n          showToast("내역을 불러왔습니다.", "success");\n        } else {\n          showToast(data.detail || "조회 내역이 없습니다.", "error");\n        }\n      } catch (err) {\n        showToast("조회 중 오류가 발생했습니다.", "error");\n      }\n    }\n  </script>\n</body>\n</html>\n', 'template:donation.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>군선교 후원 안내 | 육군학생군사학교 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n</head>\n<body class="bg-[#faf9f6] text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 헤더 -->\n  <nav class="bg-white/95 backdrop-blur border-b border-gray-200 sticky top-0 z-50">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-20">\n      <a href="/" class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-full bg-[#0f1d38] text-[#f5d77f] flex items-center justify-center text-lg shadow">\n          <i class="fa-solid fa-cross"></i>\n        </div>\n        <div>\n          <span class="text-xs font-semibold text-gray-500 uppercase block">Cadet Military School Church</span>\n          <span class="text-lg font-bold text-[#0f1d38] font-serif-kr">문무대교회 후원센터</span>\n        </div>\n      </a>\n      <div class="flex items-center gap-4 text-sm font-medium">\n        <a href="/" class="text-gray-600 hover:text-navy-900"><i class="fa-solid fa-house mr-1"></i> 메인으로</a>\n        <a href="/admin" class="text-gray-400 hover:text-gray-600 text-xs"><i class="fa-solid fa-lock mr-1"></i>관리자</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 서브 히어로 -->\n  <header class="bg-[#0f1d38] text-white py-14 px-4 relative overflow-hidden">\n    <div class="container mx-auto px-4 lg:px-8 relative z-10 max-w-4xl text-center">\n      <span class="px-3 py-1 rounded-full bg-gold-500/20 text-[#f5d77f] text-xs font-semibold border border-gold-500/30 mb-4 inline-block">\n        <i class="fa-solid fa-heart-pulse mr-1"></i> 한 생명을 구하는 청년 장교 복음화\n      </span>\n      <h1 class="text-3xl sm:text-4xl font-bold font-serif-kr mb-3">군선교 헌금 및 후원 안내</h1>\n      <p class="text-gray-300 text-sm max-w-2xl mx-auto leading-relaxed">\n        보내주시는 귀한 정성은 훈련 후보생들의 간식비, 진중세례 및 신앙도서 보급에 전액 투명하게 사용됩니다.<br>\n        입금 후 <strong>입금 알림</strong>을 남겨주시면 담당 교역자에게 실시간 알림이 전송됩니다.\n      </p>\n    </div>\n  </header>\n\n  <!-- 메인 콘텐트 -->\n  <main class="container mx-auto px-4 lg:px-8 py-12 flex-1 max-w-5xl">\n    \n    <div class="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">\n      \n      <!-- 좌측: 후원 계좌 목록 -->\n      <div class="lg:col-span-5 space-y-4">\n        <div class="flex items-center justify-between pb-2 border-b border-gray-200">\n          <h2 class="text-lg font-bold text-navy-950 font-serif-kr">공식 후원 계좌 목록</h2>\n          <span class="text-xs text-gray-500">원클릭 복사 지원</span>\n        </div>\n\n        <!-- 농협 -->\n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm relative overflow-hidden group">\n          <div class="flex justify-between items-center mb-2">\n            <span class="font-bold text-emerald-800 text-sm flex items-center gap-1.5">\n              <span class="w-2.5 h-2.5 rounded-full bg-emerald-500"></span> 농협은행 (일반 사역)\n            </span>\n            <span class="text-[11px] bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded font-semibold">대표 계좌</span>\n          </div>\n          <div class="font-mono text-xl font-extrabold text-navy-950 mb-1 select-all tracking-wider">\n            301-0284-5912-71\n          </div>\n          <div class="text-xs text-gray-500 mb-3">예금주: 육군학생군사학교 문무대교회</div>\n          <button onclick="copyAccount(\'301-0284-5912-71\', \'농협은행\')" class="w-full py-2 rounded-xl bg-gray-50 hover:bg-emerald-50 text-emerald-700 font-bold text-xs border border-gray-200 transition flex items-center justify-center gap-1.5">\n            <i class="fa-regular fa-copy"></i> 계좌번호 복사하기\n          </button>\n        </div>\n\n        <!-- 국민 -->\n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm relative overflow-hidden group">\n          <div class="flex justify-between items-center mb-2">\n            <span class="font-bold text-amber-800 text-sm flex items-center gap-1.5">\n              <span class="w-2.5 h-2.5 rounded-full bg-amber-500"></span> 국민은행 (훈련생 간식)\n            </span>\n            <span class="text-[11px] bg-amber-50 text-amber-700 px-2 py-0.5 rounded font-semibold">입영훈련 전용</span>\n          </div>\n          <div class="font-mono text-xl font-extrabold text-navy-950 mb-1 select-all tracking-wider">\n            488401-01-382910\n          </div>\n          <div class="text-xs text-gray-500 mb-3">예금주: 육군학생군사학교 문무대교회</div>\n          <button onclick="copyAccount(\'488401-01-382910\', \'국민은행\')" class="w-full py-2 rounded-xl bg-gray-50 hover:bg-amber-50 text-amber-700 font-bold text-xs border border-gray-200 transition flex items-center justify-center gap-1.5">\n            <i class="fa-regular fa-copy"></i> 계좌번호 복사하기\n          </button>\n        </div>\n\n        <!-- 신한 -->\n        <div class="bg-white p-5 rounded-2xl border border-gray-200 shadow-sm relative overflow-hidden group">\n          <div class="flex justify-between items-center mb-2">\n            <span class="font-bold text-blue-800 text-sm flex items-center gap-1.5">\n              <span class="w-2.5 h-2.5 rounded-full bg-blue-500"></span> 신한은행 (진중세례 장학)\n            </span>\n            <span class="text-[11px] bg-blue-50 text-blue-700 px-2 py-0.5 rounded font-semibold">세례 지원</span>\n          </div>\n          <div class="font-mono text-xl font-extrabold text-navy-950 mb-1 select-all tracking-wider">\n            100-032-948123\n          </div>\n          <div class="text-xs text-gray-500 mb-3">예금주: 육군학생군사학교 문무대교회</div>\n          <button onclick="copyAccount(\'100-032-948123\', \'신한은행\')" class="w-full py-2 rounded-xl bg-gray-50 hover:bg-blue-50 text-blue-700 font-bold text-xs border border-gray-200 transition flex items-center justify-center gap-1.5">\n            <i class="fa-regular fa-copy"></i> 계좌번호 복사하기\n          </button>\n        </div>\n\n        <!-- 세액공제 안내 카드 -->\n        <div class="bg-navy-900 text-white p-5 rounded-2xl border border-navy-800 text-xs space-y-2">\n          <h4 class="font-bold text-gold-400 flex items-center gap-1.5 text-sm">\n            <i class="fa-solid fa-receipt"></i> 기부금 영수증 발급 안내\n          </h4>\n          <p class="text-gray-300 leading-relaxed">\n            문무대교회는 군선교 사역 단체로서 연말정산 시 법정 기부금 세액공제 혜택(소득세법 제34조)을 받으실 수 있습니다.\n          </p>\n        </div>\n      </div>\n\n      <!-- 우측: 후원금 입금 확인 알림 전송 폼 (사용자 요구사항) -->\n      <div class="lg:col-span-7 bg-white p-6 sm:p-8 rounded-2xl border border-gray-200 shadow-sm">\n        <div class="flex items-center gap-2 mb-2">\n          <span class="w-3 h-3 rounded-full bg-emerald-500 animate-ping"></span>\n          <span class="text-xs font-bold text-emerald-600">실시간 교역자 알림 연동</span>\n        </div>\n        <h2 class="text-xl font-bold text-navy-950 font-serif-kr mb-2">후원금 입금 알림 전송</h2>\n        <p class="text-xs text-gray-500 mb-6">\n          계좌로 송금하신 후 아래 폼을 작성해 주시면, 담임목사님과 재정 담당자에게 <strong>즉시 실시간 알림</strong>이 전송됩니다.\n        </p>\n\n        <form id="donation-notify-form" onsubmit="submitDonationNotify(event)" class="space-y-4 text-xs sm:text-sm">\n          \n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">입금자 성함 (또는 교회/단체명) *</label>\n              <input type="text" id="d-name" required placeholder="예: 김성도 (서울은혜교회)" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">후원 입금 금액 (원) *</label>\n              <input type="number" id="d-amount" required min="1000" step="1000" placeholder="예: 100000" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none font-bold">\n            </div>\n          </div>\n\n          <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">입금하신 은행 *</label>\n              <select id="d-bank" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none font-medium">\n                <option value="농협은행 (301-0284-5912-71)">농협은행 (301-0284-5912-71)</option>\n                <option value="국민은행 (488401-01-382910)">국민은행 (488401-01-382910)</option>\n                <option value="신한은행 (100-032-948123)">신한은행 (100-032-948123)</option>\n                <option value="기타/타행송금">기타 은행에서 송금</option>\n              </select>\n            </div>\n            <div>\n              <label class="block font-bold text-gray-700 mb-1">후원 목적</label>\n              <select id="d-purpose" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none font-medium">\n                <option value="일반 선교 및 목회 후원">일반 선교 및 목회 후원</option>\n                <option value="하계/동계 훈련생 간식비 후원">하계/동계 훈련생 간식비 후원</option>\n                <option value="진중세례식 지원 헌금">진중세례식 지원 헌금</option>\n                <option value="기독 간부 양성 장학금">기독 간부 양성 장학금</option>\n              </select>\n            </div>\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">연락처 (감사 문자 및 영수증 안내용)</label>\n            <input type="tel" id="d-phone" placeholder="010-0000-0000" class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">응원 메시지 / 기도제목</label>\n            <textarea id="d-memo" rows="3" placeholder="문무대교회 사역자들과 훈련 후보생들을 향한 따뜻한 격려의 말씀을 적어주세요." class="w-full px-3 py-2.5 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none"></textarea>\n          </div>\n\n          <div class="flex items-center gap-2 pt-1">\n            <input type="checkbox" id="d-receipt" class="rounded w-4 h-4 text-navy-900">\n            <label for="d-receipt" class="text-gray-700 font-semibold cursor-pointer text-xs">\n              기부금 영수증(세액공제용) 발급을 희망합니다.\n            </label>\n          </div>\n\n          <button type="submit" class="w-full py-3.5 rounded-xl bg-[#0f1d38] hover:bg-[#1a2f57] text-white font-bold shadow-lg transition flex items-center justify-center gap-2 text-sm sm:text-base">\n            <i class="fa-solid fa-bell text-gold-400"></i>\n            <span>입금 확인 알림 전송하기</span>\n          </button>\n        </form>\n      </div>\n\n    </div>\n\n  </main>\n\n  <footer class="bg-[#0f1d38] text-gray-400 text-xs py-8 text-center border-t border-navy-900 mt-auto">\n    <p>© 2026 육군학생군사학교 문무대교회 재정실. 문의 043-830-1004</p>\n  </footer>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    async function submitDonationNotify(e) {\n      e.preventDefault();\n      const payload = {\n        donor_name: document.getElementById("d-name").value,\n        amount: parseInt(document.getElementById("d-amount").value, 10),\n        bank: document.getElementById("d-bank").value,\n        purpose: document.getElementById("d-purpose").value,\n        phone: document.getElementById("d-phone").value || null,\n        memo: document.getElementById("d-memo").value || null,\n        receipt_requested: document.getElementById("d-receipt").checked\n      };\n\n      try {\n        const res = await fetch("/api/donations/notify", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (data.success) {\n          showToast(data.message, "success");\n          document.getElementById("donation-notify-form").reset();\n        } else {\n          showToast("알림 전송 중 오류가 발생했습니다.", "error");\n        }\n      } catch (err) {\n        showToast("서버와 통신할 수 없습니다.", "error");\n      }\n    }\n  </script>\n</body>\n</html>\n', 'template:events.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>행사 & 진중세례 접수 | 육군학생군사학교 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n</head>\n<body class="bg-[#faf9f6] text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 헤더 -->\n  <nav class="bg-white/95 backdrop-blur border-b border-gray-200 sticky top-0 z-50">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-20">\n      <a href="/" class="flex items-center gap-3">\n        <div class="w-10 h-10 rounded-full bg-[#0f1d38] text-[#f5d77f] flex items-center justify-center text-lg shadow">\n          <i class="fa-solid fa-cross"></i>\n        </div>\n        <div>\n          <span class="text-xs font-semibold text-gray-500 uppercase block">Cadet Military School Church</span>\n          <span class="text-lg font-bold text-[#0f1d38] font-serif-kr">문무대교회 행사 & 세례센터</span>\n        </div>\n      </a>\n      <div class="flex items-center gap-4 text-sm font-medium">\n        <a href="/" class="text-gray-600 hover:text-navy-900"><i class="fa-solid fa-house mr-1"></i> 메인으로</a>\n        <a href="/admin" class="text-gray-400 hover:text-gray-600 text-xs"><i class="fa-solid fa-lock mr-1"></i>관리자</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 서브 히어로 -->\n  <header class="bg-[#0f1d38] text-white py-14 px-4 relative overflow-hidden">\n    <div class="container mx-auto px-4 lg:px-8 relative z-10 max-w-4xl text-center">\n      <span class="px-3 py-1 rounded-full bg-gold-500/20 text-[#f5d77f] text-xs font-semibold border border-gold-500/30 mb-4 inline-block">\n        <i class="fa-solid fa-water mr-1"></i> 거룩한 세례와 영적 부흥의 축제\n      </span>\n      <h1 class="text-3xl sm:text-4xl font-bold font-serif-kr mb-3">정기 종교행사 및 진중세례 안내</h1>\n      <p class="text-gray-300 text-sm max-w-2xl mx-auto leading-relaxed">\n        하나님의 군사로 거듭나는 거룩한 진중세례식과 청년 영성 캠프에 장병 및 성도 여러분을 초대합니다.<br>\n        참가를 희망하시는 분은 각 행사별로 온라인 신청을 접수해 주시기 바랍니다.\n      </p>\n    </div>\n  </header>\n\n  <!-- 행사 목록 컨테이너 -->\n  <main class="container mx-auto px-4 lg:px-8 py-12 flex-1 max-w-6xl">\n    \n    <div class="flex justify-between items-center mb-8">\n      <div>\n        <h2 class="text-xl sm:text-2xl font-bold text-navy-950 font-serif-kr">진행 중인 정기 및 특별 행사</h2>\n        <p class="text-xs sm:text-sm text-gray-500 mt-1">상세 내용을 확인하시고 참여 신청을 진행해 주세요</p>\n      </div>\n      <span class="text-xs bg-navy-900 text-gold-400 font-bold px-3 py-1 rounded-full">실시간 접수중</span>\n    </div>\n\n    <!-- 이벤트 카드 그리드 -->\n    <div id="events-grid" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">\n      <div class="col-span-full text-center py-12 text-gray-400 text-xs">\n        <i class="fa-solid fa-spinner fa-spin text-2xl mb-2"></i><br>\n        행사 목록을 불러오는 중입니다...\n      </div>\n    </div>\n\n  </main>\n\n  <!-- 참가 신청 모달 -->\n  <div id="event-reg-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-lg rounded-2xl overflow-hidden shadow-2xl flex flex-col">\n      <div class="bg-navy-950 text-white p-4 flex justify-between items-center border-b border-navy-800">\n        <div class="flex items-center gap-2">\n          <i class="fa-solid fa-ticket text-gold-400"></i>\n          <span class="font-bold text-sm" id="modal-event-title">행사 참가 신청</span>\n        </div>\n        <button onclick="closeEventRegModal()" class="text-gray-400 hover:text-white text-xl">\n          <i class="fa-solid fa-xmark"></i>\n        </button>\n      </div>\n\n      <form id="event-reg-form" onsubmit="submitEventReg(event)" class="p-6 space-y-4 text-xs sm:text-sm">\n        <input type="hidden" id="reg-event-id">\n        \n        <div>\n          <label class="block font-bold text-gray-700 mb-1">신청자 성함 *</label>\n          <input type="text" id="reg-name" required placeholder="예: 김민우 후보생 / 이은지 성도" class="w-full px-3 py-2 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">연락처 *</label>\n            <input type="tel" id="reg-phone" required placeholder="010-0000-0000" class="w-full px-3 py-2 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">소속 / 출석교회</label>\n            <input type="text" id="reg-affiliation" placeholder="예: 학군 64기 / 서울OO교회" class="w-full px-3 py-2 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">계급 또는 직분</label>\n            <input type="text" id="reg-rank" placeholder="예: 후보생, 병장, 집사, 청년" class="w-full px-3 py-2 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">동반 인원수 (본인 제외)</label>\n            <input type="number" id="reg-companions" min="0" max="10" value="0" class="w-full px-3 py-2 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none">\n          </div>\n        </div>\n\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">비고 / 세례 희망 사유</label>\n          <textarea id="reg-memo" rows="2" placeholder="세례를 처음 받으시는 경우 \'세례 신청\'이라고 기재해 주세요." class="w-full px-3 py-2 border rounded-xl focus:ring-2 focus:ring-[#0f1d38] outline-none"></textarea>\n        </div>\n\n        <div class="pt-4 flex justify-end gap-2">\n          <button type="button" onclick="closeEventRegModal()" class="px-4 py-2.5 rounded-xl bg-gray-200 text-gray-700 font-semibold">취소</button>\n          <button type="submit" class="px-6 py-2.5 rounded-xl bg-navy-900 text-white font-bold hover:bg-navy-800 transition">신청 완료하기</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <footer class="bg-[#0f1d38] text-gray-400 text-xs py-8 text-center border-t border-navy-900 mt-auto">\n    <p>© 2026 육군학생군사학교 문무대교회. 문의 043-830-1004</p>\n  </footer>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    let eventsList = [];\n\n    document.addEventListener("DOMContentLoaded", () => {\n      loadEvents();\n    });\n\n    async function loadEvents() {\n      const grid = document.getElementById("events-grid");\n      try {\n        const res = await fetch("/api/events");\n        const data = await res.json();\n        eventsList = data.events;\n\n        if (!eventsList || eventsList.length === 0) {\n          grid.innerHTML = `<div class="col-span-full p-8 text-center text-gray-400 text-xs">현재 등록된 행사 일정이 없습니다.</div>`;\n          return;\n        }\n\n        grid.innerHTML = eventsList.map(item => {\n          const percent = Math.min(100, Math.round((item.current_participants / item.max_participants) * 100));\n          const isOpen = item.is_open === 1 && item.current_participants < item.max_participants;\n\n          return `\n            <div class="bg-white rounded-2xl border border-gray-200 overflow-hidden shadow-sm hover:shadow-lg transition duration-300 flex flex-col">\n              <div class="relative h-48 bg-gray-900">\n                <img src="${item.image_url || \'https://images.unsplash.com/photo-1438232992991-995b7058bbb3?auto=format&fit=crop&w=800&q=80\'}" \n                     alt="${item.title}" \n                     class="w-full h-full object-cover">\n                <span class="absolute top-3 left-3 px-3 py-1 rounded-full text-xs font-bold bg-navy-950/80 text-gold-400 backdrop-blur border border-gold-500/30">\n                  ${item.category}\n                </span>\n                <span class="absolute top-3 right-3 px-2.5 py-1 rounded text-[11px] font-bold ${isOpen ? \'bg-emerald-500 text-white\' : \'bg-red-500 text-white\'}">\n                  ${isOpen ? \'접수중\' : \'마감\'}\n                </span>\n              </div>\n\n              <div class="p-6 flex-1 flex flex-col">\n                <h3 class="font-bold text-navy-950 text-base mb-2 font-serif-kr line-clamp-1">${item.title}</h3>\n                <p class="text-xs text-gray-500 line-clamp-2 leading-relaxed mb-4">${item.description}</p>\n\n                <div class="space-y-1.5 text-xs text-gray-600 mb-5">\n                  <div><i class="fa-regular fa-calendar text-gold-600 w-5"></i> <strong>일시:</strong> ${item.date} (${item.time})</div>\n                  <div><i class="fa-solid fa-location-dot text-gold-600 w-5"></i> <strong>장소:</strong> ${item.location}</div>\n                </div>\n\n                <!-- 정원 프로그레스 바 -->\n                <div class="mt-auto pt-4 border-t border-gray-100">\n                  <div class="flex justify-between items-center text-xs mb-1.5">\n                    <span class="text-gray-500">참여 현황</span>\n                    <span class="font-bold text-navy-900">${item.current_participants}명 / ${item.max_participants}명 (${percent}%)</span>\n                  </div>\n                  <div class="w-full bg-gray-100 rounded-full h-2 overflow-hidden mb-4">\n                    <div class="bg-gold-500 h-2 rounded-full transition-all duration-500" style="width: ${percent}%"></div>\n                  </div>\n\n                  <button onclick="openEventRegModal(${item.id})" \n                          ${!isOpen ? \'disabled\' : \'\'} \n                          class="w-full py-2.5 rounded-xl font-bold text-xs transition flex items-center justify-center gap-1.5 ${isOpen ? \'bg-navy-900 hover:bg-navy-800 text-white shadow\' : \'bg-gray-200 text-gray-400 cursor-not-allowed\'}">\n                    <i class="fa-solid fa-user-plus"></i>\n                    <span>${isOpen ? \'참가 신청하기\' : \'신청 마감\'}</span>\n                  </button>\n                </div>\n              </div>\n            </div>\n          `;\n        }).join(\'\');\n\n      } catch (err) {\n        grid.innerHTML = `<div class="col-span-full p-8 text-center text-red-500 text-xs">행사 정보를 불러올 수 없습니다.</div>`;\n      }\n    }\n\n    function openEventRegModal(eventId) {\n      const event = eventsList.find(e => e.id === eventId);\n      if (!event) return;\n\n      document.getElementById("reg-event-id").value = event.id;\n      document.getElementById("modal-event-title").innerText = `[신청] ${event.title}`;\n      document.getElementById("event-reg-modal").classList.remove("hidden");\n    }\n\n    function closeEventRegModal() {\n      document.getElementById("event-reg-modal").classList.add("hidden");\n      document.getElementById("event-reg-form").reset();\n    }\n\n    async function submitEventReg(e) {\n      e.preventDefault();\n      const eventId = document.getElementById("reg-event-id").value;\n      const payload = {\n        event_id: parseInt(eventId, 10),\n        name: document.getElementById("reg-name").value,\n        phone: document.getElementById("reg-phone").value,\n        affiliation: document.getElementById("reg-affiliation").value || null,\n        rank_or_role: document.getElementById("reg-rank").value || null,\n        companions_count: parseInt(document.getElementById("reg-companions").value, 10) || 0,\n        memo: document.getElementById("reg-memo").value || null\n      };\n\n      try {\n        const res = await fetch(`/api/events/${eventId}/register`, {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (res.ok && data.success) {\n          showToast(data.message, "success");\n          closeEventRegModal();\n          loadEvents(); // 인원 갱신\n        } else {\n          showToast(data.detail || "신청에 실패했습니다.", "error");\n        }\n      } catch (err) {\n        showToast("서버와 통신할 수 없습니다.", "error");\n      }\n    }\n  </script>\n</body>\n</html>\n', 'template:index.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>육군학생군사학교 문무대교회 | 조국 수호와 청년 복음화의 요람</title>\n  <!-- Tailwind CSS CDN -->\n  <script src="https://cdn.tailwindcss.com"></script>\n  <!-- FontAwesome 6 Icons -->\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <!-- Custom CSS -->\n  <link rel="stylesheet" href="/static/css/style.css">\n  <script>\n    tailwind.config = {\n      theme: {\n        extend: {\n          colors: {\n            navy: {\n              800: \'#142548\',\n              900: \'#0f1d38\',\n              950: \'#080f1e\',\n            },\n            gold: {\n              400: \'#f5d77f\',\n              500: \'#c59b27\',\n              600: \'#aa7c11\',\n            }\n          }\n        }\n      }\n    }\n  </script>\n</head>\n<body class="bg-[#faf9f6] text-gray-800 antialiased flex flex-col min-h-screen">\n\n  <!-- 1. 최상단 긴급 공지 & 오늘의 말씀 티커 -->\n  <div class="bg-navy-950 text-gold-400 py-2 px-4 text-xs sm:text-sm font-medium border-b border-navy-800 flex justify-between items-center">\n    <div class="container mx-auto flex flex-wrap justify-between items-center px-4">\n      <div class="flex items-center gap-2">\n        <span class="bg-gold-500/20 text-gold-400 text-xs px-2 py-0.5 rounded border border-gold-500/40 font-bold">오늘의 말씀</span>\n        <span class="text-gray-300 truncate">“너는 청년의 때에 너의 창조주를 기억하라” (전도서 12:1)</span>\n      </div>\n      <div class="hidden md:flex items-center gap-4 text-gray-400 text-xs">\n        <span><i class="fa-solid fa-location-dot text-gold-500 mr-1"></i> 충북 괴산군 괴산읍 문무로 177 영내</span>\n        <span><i class="fa-solid fa-phone text-gold-500 mr-1"></i> 군종실 043-830-1004</span>\n        <a href="/admin" class="hover:text-gold-400 transition ml-2 border-l border-gray-700 pl-3"><i class="fa-solid fa-lock text-xs mr-1"></i>관리자</a>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. 메인 글로벌 내비게이션 바 -->\n  <nav id="main-nav" class="sticky top-0 z-50 bg-white/95 backdrop-blur border-b border-gray-200 transition-all duration-300">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-20">\n      <!-- 로고 -->\n      <a href="/" class="flex items-center gap-3 group">\n        <div class="w-11 h-11 rounded-full bg-navy-900 text-gold-400 flex items-center justify-center text-xl shadow-md border border-gold-500/30 group-hover:scale-105 transition">\n          <i class="fa-solid fa-cross"></i>\n        </div>\n        <div>\n          <span class="text-xs font-semibold tracking-wider text-navy-800 uppercase block">Republic of Korea Army Cadet Military School</span>\n          <span class="text-xl font-bold text-navy-950 tracking-tight font-serif-kr flex items-center gap-2">\n            문무대교회\n            <span class="text-xs bg-navy-800 text-gold-400 px-2 py-0.5 rounded-full font-normal">육군학생군사학교</span>\n          </span>\n        </div>\n      </a>\n\n      <!-- 데스크톱 메뉴 -->\n      <div class="hidden lg:flex items-center gap-8 font-medium text-gray-700 text-sm">\n        <a href="/" class="text-navy-900 font-bold border-b-2 border-gold-500 pb-1">홈</a>\n        <a href="/about" class="hover:text-gold-600 transition">교회소개 & 연혁</a>\n        <a href="#sermon-section" class="hover:text-gold-600 transition">예배 & 말씀</a>\n        <a href="/counseling" class="hover:text-gold-600 transition flex items-center gap-1.5 text-navy-900 font-semibold bg-gold-400/10 px-3 py-1.5 rounded-full border border-gold-500/20">\n          <i class="fa-regular fa-calendar-check text-gold-600"></i> 목양상담 접수\n        </a>\n        <a href="/events" class="hover:text-gold-600 transition">행사 & 진중세례</a>\n        <a href="/consolation" class="hover:text-gold-600 transition">위문 신청</a>\n        <a href="/virtual-space" class="hover:text-gold-600 transition flex items-center gap-1 text-purple-700 font-semibold">\n          <i class="fa-solid fa-vr-cardboard"></i> 3D 가상목양실\n        </a>\n        <a href="/donation" class="hover:text-gold-600 transition">후원 안내</a>\n      </div>\n\n      <!-- 우측 빠른 CTA -->\n      <div class="hidden lg:flex items-center gap-3">\n        <a href="/counseling" class="bg-navy-900 hover:bg-navy-800 text-white text-xs font-semibold px-4 py-2.5 rounded-lg shadow transition flex items-center gap-2 border border-gold-500/30">\n          <i class="fa-solid fa-comment-dots text-gold-400"></i>\n          <span>1:1 상담 예약</span>\n        </a>\n      </div>\n\n      <!-- 모바일 햄버거 버튼 -->\n      <button id="mobile-menu-btn" class="lg:hidden text-navy-900 text-2xl focus:outline-none">\n        <i class="fa-solid fa-bars"></i>\n      </button>\n    </div>\n\n    <!-- 모바일 드롭다운 메뉴 -->\n    <div id="mobile-menu" class="hidden lg:hidden bg-white border-b border-gray-200 px-6 py-4 space-y-3 text-sm">\n      <a href="/" class="block font-bold text-navy-900 py-1">홈</a>\n      <a href="/about" class="block text-gray-700 py-1">교회소개 & 연혁</a>\n      <a href="#sermon-section" class="block text-gray-700 py-1">예배 & 말씀</a>\n      <a href="/counseling" class="block text-gold-600 font-semibold py-1">목양상담 접수 (구글캘린더 연동)</a>\n      <a href="/events" class="block text-gray-700 py-1">행사 & 진중세례</a>\n      <a href="/consolation" class="block text-gray-700 py-1">위문 신청 (중복 일정 방지)</a>\n      <a href="/virtual-space" class="block text-purple-700 font-semibold py-1">3D 가상 목양실</a>\n      <a href="/donation" class="block text-gray-700 py-1">후원 안내 & 입금 알림</a>\n      <div class="pt-2 border-t border-gray-100 flex gap-2">\n        <a href="/counseling" class="flex-1 bg-navy-900 text-white text-center py-2 rounded text-xs">상담 신청</a>\n        <a href="/admin" class="px-3 py-2 bg-gray-100 text-gray-700 rounded text-xs">관리자</a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 3. 메인 히어로 섹션 (웅장한 교회 본당 & 십자가 느낌) -->\n  <section class="relative bg-navy-950 text-white min-h-[620px] flex items-center overflow-hidden">\n    <!-- 배경 이미지 오버레이 (성스러운 대성전과 십자가) -->\n    <div class="absolute inset-0 z-0">\n      <img src="https://images.unsplash.com/photo-1548625361-195fe5795df5?auto=format&fit=crop&w=2000&q=80" \n           alt="문무대교회 대성전 전경" \n           class="w-full h-full object-cover object-center opacity-30 filter brightness-90">\n      <div class="absolute inset-0 bg-gradient-to-r from-navy-950 via-navy-950/85 to-transparent"></div>\n      <div class="absolute inset-0 bg-gradient-to-t from-navy-950 via-transparent to-transparent"></div>\n    </div>\n\n    <div class="container mx-auto px-4 lg:px-8 relative z-10 py-20">\n      <div class="max-w-2xl">\n        <div class="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-gold-500/20 border border-gold-400/40 text-gold-300 text-xs sm:text-sm font-medium mb-6">\n          <i class="fa-solid fa-shield-halved text-gold-400"></i>\n          <span>대한민국 육군학생군사학교 영내 군종교회</span>\n        </div>\n        \n        <h1 class="text-3xl sm:text-5xl lg:text-6xl font-bold tracking-tight font-serif-kr leading-tight mb-4 text-white">\n          청년 장교의 가슴마다<br>\n          <span class="gold-text-gradient">그리스도를 품게 하소서</span>\n        </h1>\n        \n        <p class="text-base sm:text-lg text-gray-300 font-normal leading-relaxed mb-8">\n          조국 수호의 최전선으로 나아갈 학군사관(ROTC)·학사장교 후보생들과 국군 장병들에게<br class="hidden sm:inline">\n          영적 전신갑주를 입히고 하나님의 거룩한 비전을 심는 복음의 요람, 문무대교회입니다.\n        </p>\n\n        <!-- CTA 버튼 그룹 -->\n        <div class="flex flex-wrap items-center gap-4">\n          <a href="/counseling" class="gold-gradient hover:opacity-90 text-navy-950 font-bold px-6 py-3.5 rounded-xl shadow-lg transition flex items-center gap-2.5">\n            <i class="fa-solid fa-calendar-check text-lg"></i>\n            <span>군종목사 상담 예약</span>\n          </a>\n          <a href="#bulletin-section" class="bg-white/10 hover:bg-white/20 text-white border border-white/20 px-6 py-3.5 rounded-xl backdrop-blur transition flex items-center gap-2">\n            <i class="fa-regular fa-newspaper text-gold-400"></i>\n            <span>이번 주 스마트 주보</span>\n          </a>\n          <a href="/virtual-space" class="bg-purple-900/40 hover:bg-purple-900/60 text-purple-200 border border-purple-400/30 px-5 py-3.5 rounded-xl backdrop-blur transition flex items-center gap-2">\n            <i class="fa-solid fa-cube text-purple-300"></i>\n            <span>3D 가상 목양실 투어</span>\n          </a>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 4. 주간 정기 예배 시간표 안내 바 (교회 필수 정보) -->\n  <section class="bg-white border-b border-gray-200 shadow-sm relative z-20 -mt-6 mx-4 lg:mx-8 rounded-2xl p-6 lg:p-8">\n    <div class="max-w-7xl mx-auto">\n      <div class="flex flex-col md:flex-row items-center justify-between pb-4 border-b border-gray-100 gap-4 mb-6">\n        <div class="flex items-center gap-3">\n          <div class="w-10 h-10 rounded-xl bg-gold-500/10 text-gold-600 flex items-center justify-center text-xl font-bold">\n            <i class="fa-regular fa-clock"></i>\n          </div>\n          <div>\n            <h2 class="text-lg font-bold text-navy-950 font-serif-kr">문무대교회 정기 예배 안내</h2>\n            <p class="text-xs text-gray-500">대성전(1,200석) 및 비전홀에서 장엄하고 은혜로운 예배가 드려집니다</p>\n          </div>\n        </div>\n        <div class="text-xs text-gray-500 bg-gray-50 px-3 py-1.5 rounded-lg border border-gray-200">\n          <i class="fa-solid fa-circle-info text-blue-500 mr-1"></i> 훈련기간 중 주일 2부는 후보생 연합예배로 진행됩니다\n        </div>\n      </div>\n\n      <div class="grid grid-cols-2 md:grid-cols-4 gap-4 text-center">\n        <!-- 주일 1부 -->\n        <div class="p-4 rounded-xl bg-gray-50 hover:bg-gold-50/50 border border-gray-100 transition">\n          <span class="inline-block px-2.5 py-0.5 rounded text-xs font-semibold bg-blue-100 text-blue-800 mb-2">장병 및 가족</span>\n          <div class="font-bold text-gray-900 text-base">주일 1부 예배</div>\n          <div class="text-xl font-extrabold text-navy-900 mt-1">주일 09:00</div>\n          <div class="text-xs text-gray-500 mt-1">대성전 (본당)</div>\n        </div>\n\n        <!-- 주일 2부 후보생 -->\n        <div class="p-4 rounded-xl bg-navy-900 text-white shadow-md border border-gold-500/30 transition relative overflow-hidden">\n          <div class="absolute top-0 right-0 bg-gold-500 text-navy-950 text-[10px] font-bold px-2 py-0.5 rounded-bl">중점 사역</div>\n          <span class="inline-block px-2.5 py-0.5 rounded text-xs font-semibold bg-gold-400 text-navy-950 mb-2">ROTC·학사 훈련생</span>\n          <div class="font-bold text-white text-base">주일 2부 연합예배</div>\n          <div class="text-xl font-extrabold text-gold-400 mt-1">주일 10:30</div>\n          <div class="text-xs text-gray-300 mt-1">대성전 (전 후보생 참여)</div>\n        </div>\n\n        <!-- 수요 찬양 -->\n        <div class="p-4 rounded-xl bg-gray-50 hover:bg-gold-50/50 border border-gray-100 transition">\n          <span class="inline-block px-2.5 py-0.5 rounded text-xs font-semibold bg-emerald-100 text-emerald-800 mb-2">찬양 & 말씀</span>\n          <div class="font-bold text-gray-900 text-base">수요 찬양기도회</div>\n          <div class="text-xl font-extrabold text-navy-900 mt-1">수요일 19:30</div>\n          <div class="text-xs text-gray-500 mt-1">비전홀 (소예배실)</div>\n        </div>\n\n        <!-- 금요 심야기도회 -->\n        <div class="p-4 rounded-xl bg-gray-50 hover:bg-gold-50/50 border border-gray-100 transition">\n          <span class="inline-block px-2.5 py-0.5 rounded text-xs font-semibold bg-purple-100 text-purple-800 mb-2">뜨거운 부르짖음</span>\n          <div class="font-bold text-gray-900 text-base">금요 심야기도회</div>\n          <div class="text-xl font-extrabold text-navy-900 mt-1">금요일 20:00</div>\n          <div class="text-xs text-gray-500 mt-1">대성전 기도처</div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 5. 6대 핵심 서비스 빠른 바로가기 카드 -->\n  <section class="py-14 bg-[#faf9f6]">\n    <div class="container mx-auto px-4 lg:px-8">\n      <div class="text-center max-w-2xl mx-auto mb-10">\n        <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr">성도 및 후보생을 위한 온라인 사역</h2>\n        <p class="text-gray-600 text-sm mt-2">문무대교회는 언제 어디서나 장병과 동행하며 영적 회복을 지원합니다</p>\n      </div>\n\n      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">\n        <!-- 1. 상담 예약 -->\n        <a href="/counseling" class="group bg-white p-6 rounded-2xl border border-gray-200/80 shadow-sm hover:shadow-xl hover:border-gold-500/50 transition-all duration-300">\n          <div class="w-12 h-12 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-2xl mb-4 group-hover:scale-110 group-hover:bg-blue-600 group-hover:text-white transition">\n            <i class="fa-solid fa-hand-holding-heart"></i>\n          </div>\n          <div class="flex items-center justify-between mb-1">\n            <h3 class="text-lg font-bold text-gray-900 group-hover:text-navy-900">목양상담 신청</h3>\n            <span class="text-xs text-blue-600 font-semibold bg-blue-50 px-2 py-0.5 rounded">구글 캘린더 연동</span>\n          </div>\n          <p class="text-sm text-gray-500 leading-relaxed mb-4">군 생활, 진로, 신앙 고충을 군종목사님과 1:1로 나누세요. 철저한 비밀보장 모드를 지원합니다.</p>\n          <div class="text-xs font-bold text-navy-900 flex items-center gap-1 group-hover:translate-x-1 transition">\n            <span>상담 시간표 확인하기</span> <i class="fa-solid fa-arrow-right text-gold-500"></i>\n          </div>\n        </a>\n\n        <!-- 2. 위문 신청 -->\n        <a href="/consolation" class="group bg-white p-6 rounded-2xl border border-gray-200/80 shadow-sm hover:shadow-xl hover:border-gold-500/50 transition-all duration-300">\n          <div class="w-12 h-12 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center text-2xl mb-4 group-hover:scale-110 group-hover:bg-amber-600 group-hover:text-white transition">\n            <i class="fa-solid fa-people-roof"></i>\n          </div>\n          <div class="flex items-center justify-between mb-1">\n            <h3 class="text-lg font-bold text-gray-900 group-hover:text-navy-900">외부 위문 신청</h3>\n            <span class="text-xs text-amber-600 font-semibold bg-amber-50 px-2 py-0.5 rounded">일정 중복방지</span>\n          </div>\n          <p class="text-sm text-gray-500 leading-relaxed mb-4">전국 교회, 동문회, 선교단체의 훈련 후보생 간식 위문 및 예배 방문 일정을 중복 없이 접수합니다.</p>\n          <div class="text-xs font-bold text-navy-900 flex items-center gap-1 group-hover:translate-x-1 transition">\n            <span>위문 캘린더 바로가기</span> <i class="fa-solid fa-arrow-right text-gold-500"></i>\n          </div>\n        </a>\n\n        <!-- 3. 행사 & 진중세례 -->\n        <a href="/events" class="group bg-white p-6 rounded-2xl border border-gray-200/80 shadow-sm hover:shadow-xl hover:border-gold-500/50 transition-all duration-300">\n          <div class="w-12 h-12 rounded-xl bg-emerald-50 text-emerald-600 flex items-center justify-center text-2xl mb-4 group-hover:scale-110 group-hover:bg-emerald-600 group-hover:text-white transition">\n            <i class="fa-solid fa-water"></i>\n          </div>\n          <div class="flex items-center justify-between mb-1">\n            <h3 class="text-lg font-bold text-gray-900 group-hover:text-navy-900">행사 & 진중세례식</h3>\n            <span class="text-xs text-emerald-600 font-semibold bg-emerald-50 px-2 py-0.5 rounded">참가 접수중</span>\n          </div>\n          <p class="text-sm text-gray-500 leading-relaxed mb-4">하계·동계 입영훈련 진중세례 및 찬양의 밤 행사 일정을 확인하고 온라인으로 신청하세요.</p>\n          <div class="text-xs font-bold text-navy-900 flex items-center gap-1 group-hover:translate-x-1 transition">\n            <span>진중세례 및 행사 안내</span> <i class="fa-solid fa-arrow-right text-gold-500"></i>\n          </div>\n        </a>\n\n        <!-- 4. 3D 가상 목양실 -->\n        <a href="/virtual-space" class="group bg-white p-6 rounded-2xl border border-purple-200/80 shadow-sm hover:shadow-xl hover:border-purple-500/50 transition-all duration-300">\n          <div class="w-12 h-12 rounded-xl bg-purple-50 text-purple-600 flex items-center justify-center text-2xl mb-4 group-hover:scale-110 group-hover:bg-purple-600 group-hover:text-white transition">\n            <i class="fa-solid fa-vr-cardboard"></i>\n          </div>\n          <div class="flex items-center justify-between mb-1">\n            <h3 class="text-lg font-bold text-gray-900 group-hover:text-purple-900">3D 가상 목양실</h3>\n            <span class="text-xs text-purple-600 font-semibold bg-purple-50 px-2 py-0.5 rounded">메타버스 체험</span>\n          </div>\n          <p class="text-sm text-gray-500 leading-relaxed mb-4">브라우저에서 360도로 목양실을 둘러보며 성경 말씀, 기도우체통, 찬양 BGM을 인터랙티브하게 체험하세요.</p>\n          <div class="text-xs font-bold text-purple-800 flex items-center gap-1 group-hover:translate-x-1 transition">\n            <span>가상공간 입장하기</span> <i class="fa-solid fa-arrow-right text-purple-600"></i>\n          </div>\n        </a>\n\n        <!-- 5. 훈련생 응원 편지함 -->\n        <div class="group bg-white p-6 rounded-2xl border border-gray-200/80 shadow-sm hover:shadow-xl hover:border-gold-500/50 transition-all duration-300 cursor-pointer" onclick="openLetterModal()">\n          <div class="w-12 h-12 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center text-2xl mb-4 group-hover:scale-110 group-hover:bg-rose-600 group-hover:text-white transition">\n            <i class="fa-solid fa-envelope-open-text"></i>\n          </div>\n          <div class="flex items-center justify-between mb-1">\n            <h3 class="text-lg font-bold text-gray-900 group-hover:text-navy-900">훈련생 응원 기도편지</h3>\n            <span class="text-xs text-rose-600 font-semibold bg-rose-50 px-2 py-0.5 rounded">주일 전달</span>\n          </div>\n          <p class="text-sm text-gray-500 leading-relaxed mb-4">입영훈련 중인 아들, 딸, 후배 장교 후보생에게 가족과 친지의 따뜻한 사랑과 기도제목을 전해주세요.</p>\n          <div class="text-xs font-bold text-navy-900 flex items-center gap-1 group-hover:translate-x-1 transition">\n            <span>응원 편지 남기기</span> <i class="fa-solid fa-arrow-right text-gold-500"></i>\n          </div>\n        </div>\n\n        <!-- 6. 후원 안내 & 입금 알림 -->\n        <a href="/donation" class="group bg-white p-6 rounded-2xl border border-gray-200/80 shadow-sm hover:shadow-xl hover:border-gold-500/50 transition-all duration-300">\n          <div class="w-12 h-12 rounded-xl bg-gold-50 text-gold-600 flex items-center justify-center text-2xl mb-4 group-hover:scale-110 group-hover:bg-gold-600 group-hover:text-white transition">\n            <i class="fa-solid fa-coins"></i>\n          </div>\n          <div class="flex items-center justify-between mb-1">\n            <h3 class="text-lg font-bold text-gray-900 group-hover:text-navy-900">군선교 후원 안내</h3>\n            <span class="text-xs text-gold-600 font-semibold bg-gold-50 px-2 py-0.5 rounded">실시간 알림 연동</span>\n          </div>\n          <p class="text-sm text-gray-500 leading-relaxed mb-4">청년 장교 복음화와 진중세례를 위한 후원 계좌를 복사하고, 입금 시 목사님께 실시간 알림을 보냅니다.</p>\n          <div class="text-xs font-bold text-navy-900 flex items-center gap-1 group-hover:translate-x-1 transition">\n            <span>계좌 확인 & 입금 알림</span> <i class="fa-solid fa-arrow-right text-gold-500"></i>\n          </div>\n        </a>\n      </div>\n    </div>\n  </section>\n\n  <!-- 6. 최신 주일 설교 영상 & 스마트 주보 섹션 (사용자 필수 요구사항 3번) -->\n  <section id="sermon-section" class="py-16 bg-white border-t border-b border-gray-200">\n    <div class="container mx-auto px-4 lg:px-8">\n      <div class="flex flex-col lg:flex-row gap-12 items-start">\n        \n        <!-- 좌측: 최신 주일 설교 유튜브 플레이어 -->\n        <div class="w-full lg:w-7/12">\n          <div class="flex items-center gap-2 mb-3">\n            <span class="w-2.5 h-2.5 rounded-full bg-red-600 animate-ping"></span>\n            <span class="text-xs font-bold text-red-600 uppercase tracking-wider">Latest Sunday Sermon</span>\n          </div>\n          <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr mb-2">주일 설교 말씀</h2>\n          <p class="text-sm text-gray-500 mb-6">청년 장교들의 영적 비전을 깨우는 문무대교회의 주일 선포 말씀입니다</p>\n\n          <!-- 반응형 16:9 유튜브 비디오 임베드 -->\n          <div class="relative w-full aspect-video rounded-2xl overflow-hidden shadow-2xl bg-black border border-gray-200">\n            <iframe id="sermon-video-frame" \n                    class="w-full h-full" \n                    src="https://www.youtube.com/embed/W5qM9uA_g28" \n                    title="문무대교회 주일설교" \n                    frameborder="0" \n                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" \n                    allowfullscreen>\n            </iframe>\n          </div>\n\n          <!-- 설교 정보 카드 -->\n          <div class="mt-4 p-5 bg-gray-50 rounded-xl border border-gray-200">\n            <div class="flex flex-wrap items-center justify-between gap-2 mb-2">\n              <span class="text-xs font-semibold px-2.5 py-1 rounded bg-navy-900 text-gold-400">주일 2부 후보생 연합예배</span>\n              <span class="text-xs text-gray-500"><i class="fa-regular fa-calendar mr-1"></i> 2026년 11월 1일 선포</span>\n            </div>\n            <h3 class="text-xl font-bold text-navy-950 mb-1">“청년의 때에 여호와를 기억하라”</h3>\n            <p class="text-sm font-semibold text-gold-600 mb-2">본문: 전도서 12장 1-2절 | 설교자: 김요한 군종목사</p>\n            <p class="text-xs text-gray-600 leading-relaxed">\n              군 복무와 훈련이라는 광야 속에서 흔들리지 않는 영적 나침반을 세우며, 야전으로 파송될 청년 장교로서 하나님을 의지하는 믿음의 결단에 대한 말씀입니다.\n            </p>\n          </div>\n        </div>\n\n        <!-- 우측: 이번 주 스마트 주보 (PDF/이미지 뷰어) -->\n        <div id="bulletin-section" class="w-full lg:w-5/12">\n          <div class="flex items-center justify-between mb-3">\n            <span class="text-xs font-bold text-navy-900 uppercase tracking-wider">Weekly Bulletin</span>\n            <span class="text-xs bg-gold-100 text-gold-800 font-bold px-2 py-0.5 rounded">제2026-44호</span>\n          </div>\n          <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr mb-2">이번 주 스마트 주보</h2>\n          <p class="text-sm text-gray-500 mb-6">스마트폰에서도 선명하게 넘겨보는 디지털 주보입니다</p>\n\n          <div class="bg-navy-950 rounded-2xl p-4 shadow-xl border border-gray-800 text-white">\n            <div class="relative rounded-xl overflow-hidden group cursor-pointer" onclick="openBulletinModal()">\n              <img src="https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=800&q=80" \n                   alt="문무대교회 주보 표지" \n                   class="w-full h-72 object-cover object-top rounded-xl group-hover:scale-105 transition duration-500">\n              <div class="absolute inset-0 bg-navy-950/60 opacity-0 group-hover:opacity-100 transition flex items-center justify-center gap-2">\n                <span class="bg-gold-500 text-navy-950 px-4 py-2 rounded-lg font-bold text-xs flex items-center gap-1.5 shadow">\n                  <i class="fa-solid fa-magnifying-glass-plus"></i> 큰 화면으로 주보 보기\n                </span>\n              </div>\n            </div>\n\n            <div class="mt-4 flex items-center justify-between pt-2 border-t border-gray-800">\n              <div>\n                <div class="font-bold text-sm text-white">2026년 11월 첫째 주일 주보</div>\n                <div class="text-xs text-gray-400 mt-0.5">예배 순서 / 목회 소식 / 훈련 일정 안내</div>\n              </div>\n              <button onclick="openBulletinModal()" class="px-3 py-1.5 rounded-lg bg-gold-500/20 text-gold-400 hover:bg-gold-500 hover:text-navy-950 text-xs font-semibold transition border border-gold-500/40">\n                주보 열기\n              </button>\n            </div>\n          </div>\n\n          <!-- 주보 주요 소식 요약 카드 -->\n          <div class="mt-4 p-4 rounded-xl border border-gray-200 bg-white shadow-sm space-y-2 text-xs">\n            <div class="font-bold text-gray-900 flex items-center gap-1.5 text-sm">\n              <i class="fa-solid fa-bullhorn text-gold-600"></i> 주보 주요 알림\n            </div>\n            <p class="text-gray-600">• <strong>하계 ROTC 진중세례식:</strong> 11월 22일(주일) 14:00 대성전</p>\n            <p class="text-gray-600">• <strong>상담 신청 안내:</strong> 일과 후 및 주말 목양상담 사전 예약 가능</p>\n            <p class="text-gray-600">• <strong>기독 간부 모임:</strong> 매주 화요일 12:00 비전홀 오찬 기도회</p>\n          </div>\n        </div>\n\n      </div>\n    </div>\n  </section>\n\n  <!-- 7. 교회 연혁 및 역사 하이라이트 (사용자 강조: 연혁 포함!) -->\n  <section class="py-16 bg-[#faf9f6]">\n    <div class="container mx-auto px-4 lg:px-8">\n      <div class="flex flex-col md:flex-row md:items-end justify-between mb-12">\n        <div>\n          <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block mb-1">Our Proud Heritage</span>\n          <h2 class="text-2xl sm:text-4xl font-bold text-navy-950 font-serif-kr">문무대교회 40년 선교 발자취</h2>\n          <p class="text-sm text-gray-600 mt-2">1985년 학생중앙군사학교 성남 시절부터 오늘날 충북 괴산 성전에 이르기까지</p>\n        </div>\n        <a href="/about" class="mt-4 md:mt-0 text-sm font-bold text-navy-900 hover:text-gold-600 flex items-center gap-1 transition">\n          전체 연혁 및 상세 소개 <i class="fa-solid fa-chevron-right text-xs text-gold-500"></i>\n        </a>\n      </div>\n\n      <!-- 타임라인 카드 그리드 -->\n      <div class="grid grid-cols-1 md:grid-cols-3 gap-6 relative">\n        <!-- 1985 -->\n        <div class="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm relative hover:-translate-y-1 transition duration-300">\n          <div class="text-3xl font-extrabold text-gold-500 font-serif-kr mb-2">1985</div>\n          <h3 class="text-lg font-bold text-navy-950 mb-2">군종 선교의 태동 (성남 시대)</h3>\n          <p class="text-xs text-gray-600 leading-relaxed mb-4">\n            경기도 성남 학생중앙군사학교 창설과 함께 장교 후보생들을 향한 영적 돌봄과 청년 복음화의 첫 등불을 밝혔습니다.\n          </p>\n          <div class="text-[11px] text-gray-400 border-t border-gray-100 pt-3">\n            <i class="fa-regular fa-calendar-check mr-1"></i> ROTC 기독장교 사역 시작\n          </div>\n        </div>\n\n        <!-- 2011 -->\n        <div class="bg-navy-900 text-white p-6 rounded-2xl border border-gold-500/40 shadow-xl relative hover:-translate-y-1 transition duration-300">\n          <div class="text-3xl font-extrabold text-gold-400 font-serif-kr mb-2">2011</div>\n          <h3 class="text-lg font-bold text-white mb-2">괴산 이전 & 대성전 헌당</h3>\n          <p class="text-xs text-gray-300 leading-relaxed mb-4">\n            충북 괴산 신축 캠퍼스로 전면 이전하며, 1,200석 규모의 현대식 대예배실과 비전홀을 갖춘 거룩한 새 성전을 헌당하였습니다.\n          </p>\n          <div class="text-[11px] text-gold-300 border-t border-navy-800 pt-3">\n            <i class="fa-regular fa-calendar-check mr-1"></i> 대한민국 육군 초급장교 선교 요충지 확립\n          </div>\n        </div>\n\n        <!-- 2026 -->\n        <div class="bg-white p-6 rounded-2xl border border-gray-200 shadow-sm relative hover:-translate-y-1 transition duration-300">\n          <div class="text-3xl font-extrabold text-gold-500 font-serif-kr mb-2">현재</div>\n          <h3 class="text-lg font-bold text-navy-950 mb-2">조국 수호와 차세대 리더 양성</h3>\n          <p class="text-xs text-gray-600 leading-relaxed mb-4">\n            연간 수천 명의 ROTC 및 학사장교 후보생이 거쳐가는 문무대에서 진중세례와 영성 훈련을 통해 기독 정예장교를 세우고 있습니다.\n          </p>\n          <div class="text-[11px] text-gray-400 border-t border-gray-100 pt-3">\n            <i class="fa-regular fa-calendar-check mr-1"></i> 스마트 군선교 및 핫라인 상담 정착\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 8. 시설 및 사역 사진 갤러리 (사용자 강조: 사진 포함!) -->\n  <section class="py-16 bg-white border-t border-gray-200">\n    <div class="container mx-auto px-4 lg:px-8">\n      <div class="text-center max-w-2xl mx-auto mb-10">\n        <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block mb-1">Photo Gallery</span>\n        <h2 class="text-2xl sm:text-4xl font-bold text-navy-950 font-serif-kr">문무대교회 시설 및 사역 현장</h2>\n        <p class="text-sm text-gray-600 mt-2">은혜와 감동이 살아 숨 쉬는 대성전과 뜨거운 예배의 순간들입니다</p>\n      </div>\n\n      <!-- 갤러리 이미지 그리드 -->\n      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">\n        <!-- 사진 1: 대성전 -->\n        <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-md bg-navy-950 aspect-[4/3]">\n          <img src="https://images.unsplash.com/photo-1548625361-195fe5795df5?auto=format&fit=crop&w=800&q=80" \n               alt="대성전 전경" \n               class="w-full h-full object-cover">\n          <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/30 to-transparent opacity-90 group-hover:opacity-100 transition p-6 flex flex-col justify-end text-white">\n            <span class="text-xs text-gold-400 font-semibold mb-1">시설 전경</span>\n            <h4 class="font-bold text-base">문무대교회 1,200석 대성전</h4>\n            <p class="text-xs text-gray-300 line-clamp-1 mt-0.5">괴산 문무대 영내에 웅장하게 자리한 예배의 처소</p>\n          </div>\n        </div>\n\n        <!-- 사진 2: 진중세례식 -->\n        <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-md bg-navy-950 aspect-[4/3]">\n          <img src="https://images.unsplash.com/photo-1438232992991-995b7058bbb3?auto=format&fit=crop&w=800&q=80" \n               alt="진중세례식" \n               class="w-full h-full object-cover">\n          <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/30 to-transparent opacity-90 group-hover:opacity-100 transition p-6 flex flex-col justify-end text-white">\n            <span class="text-xs text-gold-400 font-semibold mb-1">사역 현장</span>\n            <h4 class="font-bold text-base">하계 입영훈련 진중세례식</h4>\n            <p class="text-xs text-gray-300 line-clamp-1 mt-0.5">그리스도를 구주로 고백하는 거룩한 세례의 은혜</p>\n          </div>\n        </div>\n\n        <!-- 사진 3: 후보생 찬양 연합예배 -->\n        <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-md bg-navy-950 aspect-[4/3]">\n          <img src="https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=800&q=80" \n               alt="찬양 연합예배" \n               class="w-full h-full object-cover">\n          <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/30 to-transparent opacity-90 group-hover:opacity-100 transition p-6 flex flex-col justify-end text-white">\n            <span class="text-xs text-gold-400 font-semibold mb-1">주일 예배</span>\n            <h4 class="font-bold text-base">ROTC 후보생 연합 찬양의 밤</h4>\n            <p class="text-xs text-gray-300 line-clamp-1 mt-0.5">청년들의 뜨거운 찬양과 기도로 가득 찬 본당</p>\n          </div>\n        </div>\n\n        <!-- 사진 4: 야외 십자가 동산 -->\n        <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-md bg-navy-950 aspect-[4/3]">\n          <img src="https://images.unsplash.com/photo-1519491050282-cf00c82424b4?auto=format&fit=crop&w=800&q=80" \n               alt="야외 십자가 기도동산" \n               class="w-full h-full object-cover">\n          <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/30 to-transparent opacity-90 group-hover:opacity-100 transition p-6 flex flex-col justify-end text-white">\n            <span class="text-xs text-gold-400 font-semibold mb-1">기도 처소</span>\n            <h4 class="font-bold text-base">야외 십자가 동산 및 묵상 산책로</h4>\n            <p class="text-xs text-gray-300 line-clamp-1 mt-0.5">고요함 가운데 주님과 깊이 만나는 산책로</p>\n          </div>\n        </div>\n\n        <!-- 사진 5: 위문 행사 -->\n        <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-md bg-navy-950 aspect-[4/3]">\n          <img src="https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=800&q=80" \n               alt="위문 교제 현장" \n               class="w-full h-full object-cover">\n          <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/30 to-transparent opacity-90 group-hover:opacity-100 transition p-6 flex flex-col justify-end text-white">\n            <span class="text-xs text-gold-400 font-semibold mb-1">사랑의 나눔</span>\n            <h4 class="font-bold text-base">후원교회 위문 및 간식 전달식</h4>\n            <p class="text-xs text-gray-300 line-clamp-1 mt-0.5">어머니의 손길처럼 따뜻한 격려와 사랑</p>\n          </div>\n        </div>\n\n        <!-- 사진 6: 친교 카페 -->\n        <div class="zoom-card group relative rounded-2xl overflow-hidden shadow-md bg-navy-950 aspect-[4/3]">\n          <img src="https://images.unsplash.com/photo-1442512595331-e89e73853f31?auto=format&fit=crop&w=800&q=80" \n               alt="친교 카페" \n               class="w-full h-full object-cover">\n          <div class="absolute inset-0 bg-gradient-to-t from-navy-950/90 via-navy-950/30 to-transparent opacity-90 group-hover:opacity-100 transition p-6 flex flex-col justify-end text-white">\n            <span class="text-xs text-gold-400 font-semibold mb-1">성도 교제</span>\n            <h4 class="font-bold text-base">만남의 광장 친교 카페</h4>\n            <p class="text-xs text-gray-300 line-clamp-1 mt-0.5">예배 후 따뜻한 차와 사랑의 교제를 나누는 열린 쉼터</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 9. 오시는 길 및 부대 출입(위병소) 안내 -->\n  <section class="py-16 bg-[#faf9f6]">\n    <div class="container mx-auto px-4 lg:px-8">\n      <div class="bg-white rounded-3xl p-8 lg:p-12 border border-gray-200 shadow-sm flex flex-col lg:flex-row gap-8 items-center">\n        <div class="w-full lg:w-1/2">\n          <span class="text-xs font-bold text-gold-600 uppercase tracking-widest block mb-2">Location & Security</span>\n          <h2 class="text-2xl sm:text-3xl font-bold text-navy-950 font-serif-kr mb-4">오시는 길 & 부대 출입 안내</h2>\n          <p class="text-sm text-gray-600 leading-relaxed mb-6">\n            문무대교회는 군사보호구역인 육군학생군사학교 영내에 위치하고 있습니다. 외부 성도 및 위문 방문객께서는 위병소 출입 절차를 확인해 주시기 바랍니다.\n          </p>\n\n          <div class="space-y-4 text-sm">\n            <div class="flex items-start gap-3">\n              <div class="w-8 h-8 rounded-lg bg-navy-900 text-gold-400 flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-location-dot"></i>\n              </div>\n              <div>\n                <span class="font-bold text-gray-900 block">주소지</span>\n                <span class="text-gray-600">충청북도 괴산군 괴산읍 문무로 177 육군학생군사학교 영내 문무대교회</span>\n              </div>\n            </div>\n\n            <div class="flex items-start gap-3">\n              <div class="w-8 h-8 rounded-lg bg-navy-900 text-gold-400 flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-id-card"></i>\n              </div>\n              <div>\n                <span class="font-bold text-gray-900 block">위병소 출입 안내</span>\n                <span class="text-gray-600">주일 정기예배 참석자는 신분증(주민등록증/운전면허증) 지참 후 위병소에서 \'교회 방문\' 확인 후 출입 가능합니다.</span>\n              </div>\n            </div>\n\n            <div class="flex items-start gap-3">\n              <div class="w-8 h-8 rounded-lg bg-navy-900 text-gold-400 flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-bus"></i>\n              </div>\n              <div>\n                <span class="font-bold text-gray-900 block">단체 위문 차량</span>\n                <span class="text-gray-600">위문 단체의 경우 최소 3일 전 본 홈페이지 \'위문 신청\'을 통해 차량번호와 탑승 인원을 등록하셔야 합니다.</span>\n              </div>\n            </div>\n          </div>\n\n          <div class="mt-8 flex flex-wrap gap-3">\n            <a href="https://map.kakao.com/link/search/육군학생군사학교" target="_blank" class="px-4 py-2.5 rounded-xl bg-yellow-400 text-gray-900 font-bold text-xs hover:bg-yellow-500 transition flex items-center gap-2">\n              <i class="fa-solid fa-map-location-dot"></i> 카카오맵 길찾기\n            </a>\n            <a href="https://map.naver.com/p/search/육군학생군사학교" target="_blank" class="px-4 py-2.5 rounded-xl bg-green-600 text-white font-bold text-xs hover:bg-green-700 transition flex items-center gap-2">\n              <i class="fa-solid fa-map"></i> 네이버 지도 길찾기\n            </a>\n          </div>\n        </div>\n\n        <div class="w-full lg:w-1/2">\n          <div class="rounded-2xl overflow-hidden border border-gray-200 shadow-md aspect-video relative bg-gray-100">\n            <!-- 군부대 지도 안내 그래픽 이미지 -->\n            <img src="https://images.unsplash.com/photo-1524661135-423995f22d0b?auto=format&fit=crop&w=800&q=80" \n                 alt="문무대 위치 지도" \n                 class="w-full h-full object-cover">\n            <div class="absolute inset-0 bg-navy-950/40 flex items-center justify-center">\n              <div class="bg-white/95 backdrop-blur px-6 py-4 rounded-2xl shadow-xl text-center">\n                <i class="fa-solid fa-cross text-2xl text-gold-600 mb-1"></i>\n                <div class="font-bold text-navy-950 text-sm">육군학생군사학교 문무대교회</div>\n                <div class="text-xs text-gray-500 mt-1">충북 괴산군 괴산읍 문무로 177</div>\n                <div class="text-[11px] text-blue-600 font-semibold mt-2">정문 위병소 통과 후 안내 표지판 300m</div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- 10. 푸터 -->\n  <footer class="bg-navy-950 text-gray-400 text-xs py-12 border-t border-navy-900 mt-auto">\n    <div class="container mx-auto px-4 lg:px-8">\n      <div class="grid grid-cols-1 md:grid-cols-4 gap-8 mb-8 pb-8 border-b border-navy-900">\n        \n        <div class="md:col-span-2">\n          <div class="flex items-center gap-2 text-white font-serif-kr text-lg font-bold mb-3">\n            <i class="fa-solid fa-cross text-gold-400"></i> 육군학생군사학교 문무대교회\n          </div>\n          <p class="text-gray-400 leading-relaxed max-w-md text-xs mb-4">\n            문무대교회는 대한민국 국방의 초석이 될 청년 장교들과 훈련 후보생들의 영혼을 지키고 세우는 거룩한 군선교의 방파제입니다.\n          </p>\n          <div class="text-gray-400 space-y-1 text-xs">\n            <p>충청북도 괴산군 괴산읍 문무로 177 사서함 100호 육군학생군사학교 군종실</p>\n            <p>담임 군종목사: 김요한 소령(진) | 군종실 행정실: 043-830-1004</p>\n          </div>\n        </div>\n\n        <div>\n          <h4 class="text-white font-bold text-sm mb-3">빠른 메뉴</h4>\n          <ul class="space-y-2">\n            <li><a href="/about" class="hover:text-gold-400 transition">교회 소개 & 연혁</a></li>\n            <li><a href="/counseling" class="hover:text-gold-400 transition">목양상담 예약</a></li>\n            <li><a href="/events" class="hover:text-gold-400 transition">행사 & 진중세례</a></li>\n            <li><a href="/consolation" class="hover:text-gold-400 transition">위문 신청</a></li>\n            <li><a href="/virtual-space" class="hover:text-gold-400 transition">3D 가상 목양실</a></li>\n          </ul>\n        </div>\n\n        <div>\n          <h4 class="text-white font-bold text-sm mb-3">군선교 헌금 계좌</h4>\n          <div class="bg-navy-900 p-3 rounded-xl border border-navy-800 space-y-2">\n            <div class="text-gray-300 font-semibold text-xs">농협은행</div>\n            <div class="text-gold-400 font-mono font-bold text-sm select-all">301-0284-5912-71</div>\n            <div class="text-[11px] text-gray-400">예금주: 문무대교회</div>\n            <button onclick="copyAccount(\'301-0284-5912-71\', \'농협\')" class="w-full mt-1 bg-navy-800 hover:bg-navy-700 text-gold-400 py-1 rounded text-[11px] font-semibold transition border border-gold-500/20">\n              계좌번호 복사\n            </button>\n          </div>\n        </div>\n\n      </div>\n\n      <div class="flex flex-col sm:flex-row items-center justify-between gap-4 text-gray-500 text-[11px]">\n        <div>© 2026 Republic of Korea Army Cadet Military School Church. All Rights Reserved.</div>\n        <div class="flex items-center gap-4">\n          <a href="/admin" class="hover:text-gray-400 transition"><i class="fa-solid fa-lock text-xs mr-1"></i>군종행정 관리자 로그인</a>\n        </div>\n      </div>\n    </div>\n  </footer>\n\n  <!-- 스마트 주보 모달 다이얼로그 -->\n  <div id="bulletin-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-4xl rounded-2xl overflow-hidden shadow-2xl flex flex-col max-h-[90vh]">\n      <div class="bg-navy-950 text-white p-4 flex justify-between items-center border-b border-navy-800">\n        <div class="flex items-center gap-2">\n          <i class="fa-solid fa-newspaper text-gold-400"></i>\n          <span class="font-bold text-sm">문무대교회 스마트 주보 (제2026-44호)</span>\n        </div>\n        <button onclick="closeBulletinModal()" class="text-gray-400 hover:text-white text-xl">\n          <i class="fa-solid fa-xmark"></i>\n        </button>\n      </div>\n      <div class="p-4 overflow-y-auto flex-1 bg-gray-100 flex flex-col items-center">\n        <img src="https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1200&q=80" \n             alt="주보 고화질 이미지" \n             class="w-full max-w-2xl rounded-lg shadow-md mb-4">\n        <div class="bg-white p-6 rounded-xl shadow w-full max-w-2xl text-sm space-y-4">\n          <div class="border-b pb-3">\n            <h4 class="font-bold text-navy-950 text-base">주일 예배 순서 (2026년 11월 1일)</h4>\n            <p class="text-xs text-gray-500">인도: 김요한 군종목사 | 찬양: 문무대 찬양팀</p>\n          </div>\n          <div class="space-y-2 text-xs">\n            <div class="flex justify-between py-1 border-b border-gray-100">\n              <span class="font-semibold text-gray-700">예배의 부름</span>\n              <span class="text-gray-500">인도자</span>\n            </div>\n            <div class="flex justify-between py-1 border-b border-gray-100">\n              <span class="font-semibold text-gray-700">찬송</span>\n              <span class="text-gray-500">통일찬송가 358장 (주의 진리 위해 십자가 군기)</span>\n            </div>\n            <div class="flex justify-between py-1 border-b border-gray-100">\n              <span class="font-semibold text-gray-700">대표기도</span>\n              <span class="text-gray-500">ROTC 후보생 대표</span>\n            </div>\n            <div class="flex justify-between py-1 border-b border-gray-100">\n              <span class="font-semibold text-gray-700">성경봉독</span>\n              <span class="text-gray-500">전도서 12장 1-2절</span>\n            </div>\n            <div class="flex justify-between py-1 border-b border-gray-100">\n              <span class="font-semibold text-gray-700">말씀선포</span>\n              <span class="font-bold text-navy-900">“청년의 때에 여호와를 기억하라” (김요한 목사)</span>\n            </div>\n            <div class="flex justify-between py-1">\n              <span class="font-semibold text-gray-700">축도</span>\n              <span class="text-gray-500">김요한 군종목사</span>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div class="bg-gray-50 p-4 border-t border-gray-200 flex justify-end gap-3">\n        <button onclick="showToast(\'주보 PDF 다운로드가 시작되었습니다.\', \'success\')" class="px-4 py-2 rounded-xl bg-navy-900 text-gold-400 text-xs font-bold hover:bg-navy-800 transition flex items-center gap-1.5">\n          <i class="fa-solid fa-download"></i> PDF 다운로드\n        </button>\n        <button onclick="closeBulletinModal()" class="px-4 py-2 rounded-xl bg-gray-200 text-gray-700 text-xs font-semibold hover:bg-gray-300 transition">\n          닫기\n        </button>\n      </div>\n    </div>\n  </div>\n\n  <!-- 훈련생 응원 편지 작성 모달 -->\n  <div id="letter-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-white w-full max-w-lg rounded-2xl overflow-hidden shadow-2xl flex flex-col">\n      <div class="bg-navy-950 text-white p-4 flex justify-between items-center border-b border-navy-800">\n        <div class="flex items-center gap-2">\n          <i class="fa-solid fa-envelope-open-text text-rose-400"></i>\n          <span class="font-bold text-sm">훈련생 응원 & 기도 편지 보내기</span>\n        </div>\n        <button onclick="closeLetterModal()" class="text-gray-400 hover:text-white text-xl">\n          <i class="fa-solid fa-xmark"></i>\n        </button>\n      </div>\n      <form id="letter-form" onsubmit="submitLetter(event)" class="p-6 space-y-4 text-xs">\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">받는 후보생 / 장병 이름 *</label>\n          <input type="text" id="letter-recipient" required placeholder="예: 김민석 후보생 (ROTC 64기)" class="w-full px-3 py-2 border rounded-lg focus:outline-none focus:border-navy-900">\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">소속 부대 / 교육여단 *</label>\n          <input type="text" id="letter-unit" required placeholder="예: 교육여단 2대대 3중대 1소대" class="w-full px-3 py-2 border rounded-lg focus:outline-none focus:border-navy-900">\n        </div>\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">보내는 분 성함 *</label>\n            <input type="text" id="letter-sender" required placeholder="예: 어머니 이혜숙" class="w-full px-3 py-2 border rounded-lg focus:outline-none focus:border-navy-900">\n          </div>\n          <div>\n            <label class="block font-bold text-gray-700 mb-1">관계 *</label>\n            <select id="letter-relation" class="w-full px-3 py-2 border rounded-lg focus:outline-none focus:border-navy-900">\n              <option value="가족(부모/형제)">가족 (부모/형제)</option>\n              <option value="친구/선후배">친구 / 동기 / 선후배</option>\n              <option value="출석교회 성도">출석교회 성도 / 목회자</option>\n              <option value="기타">기타</option>\n            </select>\n          </div>\n        </div>\n        <div>\n          <label class="block font-bold text-gray-700 mb-1">응원 메시지 & 기도제목 *</label>\n          <textarea id="letter-content" required rows="4" placeholder="훈련 중인 후보생에게 힘이 되는 따뜻한 응원의 말씀이나 성경 구절을 남겨주세요." class="w-full px-3 py-2 border rounded-lg focus:outline-none focus:border-navy-900"></textarea>\n        </div>\n        <div class="flex items-center gap-2 pt-2">\n          <input type="checkbox" id="letter-private" class="rounded text-navy-900">\n          <label for="letter-private" class="text-gray-600">비공개 편지로 전달 (주일 예배 시 해당 후보생에게만 출력 전달)</label>\n        </div>\n        <div class="pt-4 flex justify-end gap-2">\n          <button type="button" onclick="closeLetterModal()" class="px-4 py-2 rounded-lg bg-gray-200 text-gray-700 font-semibold">취소</button>\n          <button type="submit" class="px-5 py-2 rounded-lg bg-navy-900 text-white font-bold hover:bg-navy-800 transition">편지 접수하기</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <script src="/static/js/main.js"></script>\n  <script>\n    function openBulletinModal() {\n      document.getElementById("bulletin-modal").classList.remove("hidden");\n    }\n    function closeBulletinModal() {\n      document.getElementById("bulletin-modal").classList.add("hidden");\n    }\n    function openLetterModal() {\n      document.getElementById("letter-modal").classList.remove("hidden");\n    }\n    function closeLetterModal() {\n      document.getElementById("letter-modal").classList.add("hidden");\n    }\n\n    async function submitLetter(e) {\n      e.preventDefault();\n      const payload = {\n        recipient_name: document.getElementById("letter-recipient").value,\n        recipient_unit: document.getElementById("letter-unit").value,\n        sender_name: document.getElementById("letter-sender").value,\n        sender_relation: document.getElementById("letter-relation").value,\n        content: document.getElementById("letter-content").value,\n        is_private: document.getElementById("letter-private").checked\n      };\n\n      try {\n        const res = await fetch("/api/letters", {\n          method: "POST",\n          headers: { "Content-Type": "application/json" },\n          body: JSON.stringify(payload)\n        });\n        const data = await res.json();\n        if (data.success) {\n          showToast(data.message, "success");\n          closeLetterModal();\n          document.getElementById("letter-form").reset();\n        } else {\n          showToast(data.detail || "오류가 발생했습니다.", "error");\n        }\n      } catch (err) {\n        showToast("서버와 통신할 수 없습니다.", "error");\n      }\n    }\n  </script>\n</body>\n</html>\n', 'template:virtual_space.html': '<!DOCTYPE html>\n<html lang="ko">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>3D 인터랙티브 가상 목양실 | 육군학생군사학교 문무대교회</title>\n  <script src="https://cdn.tailwindcss.com"></script>\n  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css">\n  <link rel="stylesheet" href="/static/css/style.css">\n  <!-- Three.js & OrbitControls CDN -->\n  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n  <script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script>\n  <style>\n    #canvas-container {\n      width: 100%;\n      height: 72vh;\n      min-height: 500px;\n      position: relative;\n      touch-action: none;\n    }\n  </style>\n</head>\n<body class="bg-navy-950 text-white antialiased flex flex-col min-h-screen overflow-hidden">\n\n  <!-- 헤더 -->\n  <nav class="bg-navy-950/90 backdrop-blur border-b border-navy-800 z-30">\n    <div class="container mx-auto px-4 lg:px-8 flex justify-between items-center h-16">\n      <a href="/" class="flex items-center gap-2.5">\n        <div class="w-8 h-8 rounded-full bg-gold-500/20 text-gold-400 flex items-center justify-center text-sm border border-gold-500/40">\n          <i class="fa-solid fa-vr-cardboard"></i>\n        </div>\n        <div>\n          <span class="text-sm font-bold text-white font-serif-kr">문무대교회 3D 가상 목양실</span>\n          <span class="text-[10px] text-gold-400 ml-1.5 hidden sm:inline">Online Virtual Chaplain\'s Office</span>\n        </div>\n      </a>\n      \n      <div class="flex items-center gap-3">\n        <button id="btn-bgm-toggle" onclick="toggleBgm()" class="px-3 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-semibold text-gray-200 transition border border-gray-700 flex items-center">\n          <i class="fa-solid fa-volume-high text-gold-400 mr-1.5"></i> 찬양 BGM 켜기\n        </button>\n        <a href="/" class="text-xs text-gray-400 hover:text-white transition px-2 py-1">\n          <i class="fa-solid fa-arrow-left mr-1"></i> 메인으로\n        </a>\n      </div>\n    </div>\n  </nav>\n\n  <!-- 가상공간 조작 팁 오버레이 배너 -->\n  <div class="bg-navy-900/80 border-b border-navy-800 py-1.5 px-4 text-center text-xs text-gold-300 font-medium z-20">\n    <i class="fa-solid fa-hand-pointer mr-1.5 animate-bounce"></i>\n    마우스 드래그로 360° 회전 및 휠 줌 가능 | 반짝이는 <strong>십자가, 성경책, 소파</strong>를 클릭해 보세요!\n  </div>\n\n  <!-- 3D 캔버스 영역 -->\n  <div class="flex-1 relative bg-navy-950 flex flex-col justify-center items-center">\n    <div id="canvas-container"></div>\n\n    <!-- 하단 카메라 포커스 퀵 버튼 바 -->\n    <div class="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 flex flex-wrap items-center justify-center gap-2 bg-navy-900/90 backdrop-blur p-2 rounded-2xl border border-navy-700 shadow-2xl">\n      <button onclick="focusCamera(\'all\')" class="px-3 py-1.5 rounded-xl text-xs font-bold bg-navy-800 hover:bg-navy-700 text-gray-200 transition flex items-center gap-1.5">\n        <i class="fa-solid fa-eye"></i> 전체 보기\n      </button>\n      <button onclick="focusCamera(\'cross\')" class="px-3 py-1.5 rounded-xl text-xs font-bold bg-navy-800 hover:bg-navy-700 text-gold-400 transition flex items-center gap-1.5">\n        <i class="fa-solid fa-cross"></i> 십자가 묵상\n      </button>\n      <button onclick="focusCamera(\'desk\')" class="px-3 py-1.5 rounded-xl text-xs font-bold bg-navy-800 hover:bg-navy-700 text-blue-300 transition flex items-center gap-1.5">\n        <i class="fa-solid fa-book-bible"></i> 목양 책상\n      </button>\n      <button onclick="focusCamera(\'sofa\')" class="px-3 py-1.5 rounded-xl text-xs font-bold bg-navy-800 hover:bg-navy-700 text-amber-300 transition flex items-center gap-1.5">\n        <i class="fa-solid fa-couch"></i> 상담 소파\n      </button>\n    </div>\n  </div>\n\n  <!-- 십자가 묵상 & 오늘의 축복기도 모달 -->\n  <div id="prayer-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-navy-900 border border-gold-500/40 w-full max-w-lg rounded-2xl overflow-hidden shadow-2xl p-6 sm:p-8 text-center space-y-4">\n      <div class="w-14 h-14 rounded-full bg-gold-500/20 text-gold-400 flex items-center justify-center text-2xl mx-auto border border-gold-500/30">\n        <i class="fa-solid fa-cross"></i>\n      </div>\n      <span class="text-xs font-bold text-gold-400 uppercase tracking-widest block">Daily Blessing & Prayer</span>\n      <h3 class="text-2xl font-bold font-serif-kr text-white">청년 장교를 위한 담임목사의 축복기도</h3>\n      \n      <div class="p-5 bg-navy-950 rounded-xl border border-navy-800 text-left text-xs sm:text-sm text-gray-300 leading-relaxed font-serif-kr space-y-3">\n        <p>\n          “만군의 주 하나님 아버지, 오늘도 조국의 부름을 받고 땀 흘리는 사랑하는 문무대 후보생들과 장병들을 기억하옵소서.\n        </p>\n        <p>\n          지친 무릎을 세워주시고, 연약한 손을 붙들어 주시며, 군 생활의 모든 광야가 주님의 거룩한 리더로 단련되는 축복의 통로가 되게 하옵소서.\n        </p>\n        <p>\n          ‘내가 네게 명령한 것이 아니냐 강하고 담대하라 두려워하지 말며 놀라지 말라 네가 어디로 가든지 네 하나님 여호와가 너와 함께 하느니라’ (여호수아 1:9) 아멘.”\n        </p>\n      </div>\n\n      <button onclick="closeModal(\'prayer-modal\')" class="w-full py-3 rounded-xl bg-gold-500 hover:bg-gold-600 text-navy-950 font-bold text-xs transition">\n        기도를 마음에 담고 닫기\n      </button>\n    </div>\n  </div>\n\n  <!-- 성경 말씀 카드 모달 -->\n  <div id="bible-modal" class="hidden fixed inset-0 z-50 flex items-center justify-center p-4 modal-overlay">\n    <div class="bg-navy-900 border border-navy-700 w-full max-w-lg rounded-2xl overflow-hidden shadow-2xl p-6 sm:p-8 space-y-4">\n      <div class="flex justify-between items-center border-b border-navy-800 pb-3">\n        <div class="flex items-center gap-2 text-gold-400 font-bold text-sm">\n          <i class="fa-solid fa-book-bible"></i> 후보생 필독 말씀\n        </div>\n        <button onclick="closeModal(\'bible-modal\')" class="text-gray-400 hover:text-white text-xl">\n          <i class="fa-solid fa-xmark"></i>\n        </button>\n      </div>\n\n      <div class="space-y-3 text-xs sm:text-sm text-gray-300">\n        <div class="p-4 bg-navy-950 rounded-xl border border-navy-800">\n          <span class="text-gold-400 font-bold block mb-1">디모데후서 2:3</span>\n          <p class="leading-relaxed">“너는 그리스도 예수의 좋은 병사로 나와 함께 고난을 받으라”</p>\n        </div>\n        <div class="p-4 bg-navy-950 rounded-xl border border-navy-800">\n          <span class="text-gold-400 font-bold block mb-1">시편 91:1-2</span>\n          <p class="leading-relaxed">“지존자의 은밀한 곳에 거주하며 전능자의 그늘 아래에 사는 자여, 나는 여호와를 향하여 말하기를 그는 나의 피난처요 나의 요새요 내가 의뢰하는 하나님이라 하리니”</p>\n        </div>\n      </div>\n\n      <button onclick="closeModal(\'bible-modal\')" class="w-full py-2.5 rounded-xl bg-navy-800 hover:bg-navy-700 text-gray-300 font-semibold text-xs transition">\n        닫기\n      </button>\n    </div>\n  </div>\n\n  <script src="/static/js/main.js"></script>\n  <script src="/static/js/virtual_space.js"></script>\n  <script>\n    function openModal(id) {\n      document.getElementById(id).classList.remove("hidden");\n    }\n    function closeModal(id) {\n      document.getElementById(id).classList.add("hidden");\n    }\n  </script>\n</body>\n</html>\n', 'static:static/css/style.css': "/* 문무대교회 디자인 시스템 스타일시트 */\n@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/static/pretendard.css');\n@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;600;700&display=swap');\n\n:root {\n  --primary-navy: #0f1d38;\n  --primary-deep: #0a1324;\n  --accent-gold: #c59b27;\n  --accent-gold-light: #f3e5ab;\n  --accent-gold-dark: #9a7618;\n  --bg-cream: #faf9f6;\n  --text-main: #1f2937;\n  --text-muted: #6b7280;\n  --border-light: #e5e7eb;\n}\n\nbody {\n  font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, Roboto, sans-serif;\n  color: var(--text-main);\n  background-color: var(--bg-cream);\n  overflow-x: hidden;\n}\n\n.font-serif-kr {\n  font-family: 'Noto Serif KR', serif;\n}\n\n/* 성스러운 금빛 그라데이션 */\n.gold-gradient {\n  background: linear-gradient(135deg, #d4af37 0%, #aa7c11 100%);\n}\n\n.gold-text-gradient {\n  background: linear-gradient(135deg, #f5d77f 0%, #d4af37 50%, #aa7c11 100%);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n}\n\n.navy-gradient {\n  background: linear-gradient(135deg, #0f1d38 0%, #1a2f57 100%);\n}\n\n/* 부드러운 스크롤 */\nhtml {\n  scroll-behavior: smooth;\n}\n\n/* 커스텀 스크롤바 */\n::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n::-webkit-scrollbar-track {\n  background: #f1f1f1;\n}\n::-webkit-scrollbar-thumb {\n  background: #cbd5e1;\n  border-radius: 4px;\n}\n::-webkit-scrollbar-thumb:hover {\n  background: #94a3b8;\n}\n\n/* 토스트 알림창 애니메이션 */\n#toast-container {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  z-index: 9999;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.toast {\n  min-width: 280px;\n  max-width: 400px;\n  padding: 14px 18px;\n  border-radius: 10px;\n  background-color: #1e293b;\n  color: #fff;\n  box-shadow: 0 10px 25px rgba(0,0,0,0.2);\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  font-size: 0.95rem;\n  animation: slideIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n  transition: all 0.3s ease;\n}\n\n.toast.toast-success {\n  border-left: 4px solid #10b981;\n}\n\n.toast.toast-error {\n  border-left: 4px solid #ef4444;\n}\n\n.toast.toast-info {\n  border-left: 4px solid #3b82f6;\n}\n\n@keyframes slideIn {\n  from {\n    transform: translateX(100%);\n    opacity: 0;\n  }\n  to {\n    transform: translateX(0);\n    opacity: 1;\n  }\n}\n\n/* 빛나는 십자가/버튼 펄스 효과 */\n@keyframes pulseGlow {\n  0%, 100% {\n    box-shadow: 0 0 15px rgba(212, 175, 55, 0.4);\n  }\n  50% {\n    box-shadow: 0 0 30px rgba(212, 175, 55, 0.8);\n  }\n}\n\n.pulse-glow {\n  animation: pulseGlow 3s infinite ease-in-out;\n}\n\n/* 이미지 호버 줌 */\n.zoom-card {\n  overflow: hidden;\n}\n.zoom-card img {\n  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);\n}\n.zoom-card:hover img {\n  transform: scale(1.05);\n}\n\n/* 모달 오버레이 */\n.modal-overlay {\n  background-color: rgba(15, 29, 56, 0.75);\n  backdrop-filter: blur(4px);\n}\n", 'static:static/js/main.js': '// 문무대교회 공통 프론트엔드 유틸리티\ndocument.addEventListener("DOMContentLoaded", () => {\n    // 모바일 햄버거 메뉴 토글\n    const mobileBtn = document.getElementById("mobile-menu-btn");\n    const mobileMenu = document.getElementById("mobile-menu");\n    if (mobileBtn && mobileMenu) {\n        mobileBtn.addEventListener("click", () => {\n            mobileMenu.classList.toggle("hidden");\n        });\n    }\n\n    // 네비게이션 스크롤 스타일링\n    const navbar = document.getElementById("main-nav");\n    if (navbar) {\n        window.addEventListener("scroll", () => {\n            if (window.scrollY > 40) {\n                navbar.classList.add("bg-white/95", "shadow-md", "backdrop-blur-md");\n                navbar.classList.remove("bg-white/90");\n            } else {\n                navbar.classList.add("bg-white/90");\n                navbar.classList.remove("shadow-md");\n            }\n        });\n    }\n});\n\n// 토스트 메시지 시스템\nfunction showToast(message, type = "info") {\n    let container = document.getElementById("toast-container");\n    if (!container) {\n        container = document.createElement("div");\n        container.id = "toast-container";\n        document.body.appendChild(container);\n    }\n\n    const toast = document.createElement("div");\n    toast.className = `toast toast-${type}`;\n    \n    let icon = "fa-info-circle text-blue-400";\n    if (type === "success") icon = "fa-check-circle text-emerald-400";\n    if (type === "error") icon = "fa-exclamation-circle text-rose-400";\n\n    toast.innerHTML = `\n        <i class="fa-solid ${icon} text-lg"></i>\n        <div class="flex-1">${message}</div>\n    `;\n\n    container.appendChild(toast);\n\n    setTimeout(() => {\n        toast.style.opacity = "0";\n        toast.style.transform = "translateX(100%)";\n        setTimeout(() => toast.remove(), 300);\n    }, 4000);\n}\n\n// 계좌번호 원클릭 복사\nfunction copyAccount(accountNumber, bankName) {\n    if (navigator.clipboard) {\n        navigator.clipboard.writeText(accountNumber).then(() => {\n            showToast(`${bankName} 계좌번호(${accountNumber})가 클립보드에 복사되었습니다.`, "success");\n        }).catch(() => {\n            fallbackCopy(accountNumber, bankName);\n        });\n    } else {\n        fallbackCopy(accountNumber, bankName);\n    }\n}\n\nfunction fallbackCopy(text, bankName) {\n    const textarea = document.createElement("textarea");\n    textarea.value = text;\n    document.body.appendChild(textarea);\n    textarea.select();\n    document.execCommand("copy");\n    document.body.removeChild(textarea);\n    showToast(`${bankName} 계좌번호가 복사되었습니다.`, "success");\n}\n\n// ics 캘린더 파일 다운로드 생성기\nfunction downloadIcsFile(title, dateStr, timeStr, details, location = "육군학생군사학교 문무대교회 목양실") {\n    try {\n        const parts = timeStr.split("-");\n        const startPart = parts[0].trim().replace("오전", "").replace("오후", "").replace("야간", "").trim();\n        const endPart = parts[1] ? parts[1].split("(")[0].trim() : startPart;\n\n        const startClean = dateStr.replace(/-/g, "") + "T" + startPart.replace(":", "") + "00";\n        const endClean = dateStr.replace(/-/g, "") + "T" + endPart.replace(":", "") + "00";\n\n        const icsData = [\n            "BEGIN:VCALENDAR",\n            "VERSION:2.0",\n            "PRODID:-//Munmu Church//Counseling System//KO",\n            "BEGIN:VEVENT",\n            `SUMMARY:${title}`,\n            `DESCRIPTION:${details.replace(/\\n/g, "\\\\n")}`,\n            `LOCATION:${location}`,\n            `DTSTART:${startClean}`,\n            `DTEND:${endClean}`,\n            "STATUS:CONFIRMED",\n            "END:VEVENT",\n            "END:VCALENDAR"\n        ].join("\\r\\n");\n\n        const blob = new Blob([icsData], { type: "text/calendar;charset=utf-8" });\n        const link = document.createElement("a");\n        link.href = window.URL.createObjectURL(blob);\n        link.setAttribute("download", `문무대교회_상담일정_${dateStr}.ics`);\n        document.body.appendChild(link);\n        link.click();\n        document.body.removeChild(link);\n    } catch (e) {\n        console.error("ICS generation error:", e);\n    }\n}\n', 'static:static/js/virtual_space.js': '// Three.js 기반 문무대교회 3D 인터랙티브 가상 목양실\nlet scene, camera, renderer, controls;\nlet raycaster, mouse;\nlet interactiveObjects = [];\nlet audioPlaying = false;\nlet bgmAudio = null;\n\ndocument.addEventListener("DOMContentLoaded", () => {\n    initThreeSpace();\n    initAudio();\n});\n\nfunction initAudio() {\n    // 경건하고 잔잔한 로열티 프리 찬양 피아노 음원\n    bgmAudio = new Audio("https://cdn.freesound.org/previews/612/612089_11861866-lq.mp3");\n    bgmAudio.loop = true;\n    bgmAudio.volume = 0.4;\n}\n\nfunction toggleBgm() {\n    const btn = document.getElementById("btn-bgm-toggle");\n    if (!bgmAudio) return;\n\n    if (audioPlaying) {\n        bgmAudio.pause();\n        audioPlaying = false;\n        if (btn) btn.innerHTML = `<i class="fa-solid fa-volume-xmark mr-1"></i> BGM 켜기`;\n        showToast("찬양 배경음악이 일시정지되었습니다.", "info");\n    } else {\n        bgmAudio.play().then(() => {\n            audioPlaying = true;\n            if (btn) btn.innerHTML = `<i class="fa-solid fa-volume-high text-gold-400 mr-1 animate-pulse"></i> BGM 끄기`;\n            showToast("은혜로운 피아노 찬양이 재생됩니다.", "success");\n        }).catch(e => {\n            console.log("Audio play blocked:", e);\n            showToast("오디오 재생을 위해 화면을 한 번 클릭해 주세요.", "info");\n        });\n    }\n}\n\nfunction initThreeSpace() {\n    const container = document.getElementById("canvas-container");\n    if (!container) return;\n\n    // 1. 씬 및 카메라 설정\n    scene = new THREE.Scene();\n    scene.background = new THREE.Color(0x0f1d38);\n    scene.fog = new THREE.FogExp2(0x0f1d38, 0.035);\n\n    camera = new THREE.PerspectiveCamera(60, container.clientWidth / container.clientHeight, 0.1, 1000);\n    camera.position.set(0, 4.5, 9);\n\n    // 2. 렌더러 설정\n    renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });\n    renderer.setSize(container.clientWidth, container.clientHeight);\n    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n    renderer.shadowMap.enabled = true;\n    renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n    container.appendChild(renderer.domElement);\n\n    // 3. 궤도 컨트롤러 (마우스 회전/줌)\n    controls = new THREE.OrbitControls(camera, renderer.domElement);\n    controls.enableDamping = true;\n    controls.dampingFactor = 0.05;\n    controls.maxPolarAngle = Math.PI / 2 + 0.05; // 바닥 밑으로 못 내려가게\n    controls.minDistance = 2;\n    controls.maxDistance = 14;\n    controls.target.set(0, 2, 0);\n\n    // 4. 조명 시스템 (따뜻하고 은혜로운 빛)\n    const ambientLight = new THREE.AmbientLight(0xfff6e5, 0.7);\n    scene.add(ambientLight);\n\n    // 십자가 집중 조명\n    const crossSpot = new THREE.SpotLight(0xffd700, 2.5);\n    crossSpot.position.set(0, 8, 2);\n    crossSpot.target.position.set(0, 3.5, -5.8);\n    crossSpot.angle = Math.PI / 4;\n    crossSpot.penumbra = 0.8;\n    crossSpot.castShadow = true;\n    scene.add(crossSpot);\n    scene.add(crossSpot.target);\n\n    // 방 내부 따뜻한 포인트 라이트\n    const roomLight = new THREE.PointLight(0xffecd2, 1.2, 20);\n    roomLight.position.set(2, 6, 2);\n    scene.add(roomLight);\n\n    // 5. 3D 목양실 룸 구축\n    buildRoom();\n\n    // 6. 가구 및 인터랙티브 오브젝트 추가\n    buildFurniture();\n\n    // 7. 레이캐스터 (클릭 감지)\n    raycaster = new THREE.Raycaster();\n    mouse = new THREE.Vector2();\n\n    renderer.domElement.addEventListener("click", onDocumentClick);\n    window.addEventListener("resize", onWindowResize);\n\n    // 8. 렌더 루프\n    animate();\n}\n\nfunction buildRoom() {\n    // 바닥 (고급 원목 마루 텍스처 느낌)\n    const floorGeo = new THREE.PlaneGeometry(16, 16);\n    const floorMat = new THREE.MeshStandardMaterial({ color: 0x4a2e18, roughness: 0.6, metalness: 0.1 });\n    const floor = new THREE.Mesh(floorGeo, floorMat);\n    floor.rotation.x = -Math.PI / 2;\n    floor.receiveShadow = true;\n    scene.add(floor);\n\n    // 중앙 원형 러그\n    const rugGeo = new THREE.CircleGeometry(3.8, 32);\n    const rugMat = new THREE.MeshStandardMaterial({ color: 0x8b1c1c, roughness: 0.9 });\n    const rug = new THREE.Mesh(rugGeo, rugMat);\n    rug.rotation.x = -Math.PI / 2;\n    rug.position.y = 0.01;\n    scene.add(rug);\n\n    // 뒷벽 (십자가 걸린 벽)\n    const backWallGeo = new THREE.PlaneGeometry(16, 8);\n    const backWallMat = new THREE.MeshStandardMaterial({ color: 0x1b2845, roughness: 0.8 });\n    const backWall = new THREE.Mesh(backWallGeo, backWallMat);\n    backWall.position.set(0, 4, -6);\n    scene.add(backWall);\n\n    // 좌측 벽\n    const leftWall = new THREE.Mesh(backWallGeo, backWallMat);\n    leftWall.rotation.y = Math.PI / 2;\n    leftWall.position.set(-6, 4, 0);\n    scene.add(leftWall);\n\n    // 우측 벽 (창문이 있는 벽)\n    const rightWall = new THREE.Mesh(backWallGeo, backWallMat);\n    rightWall.rotation.y = -Math.PI / 2;\n    rightWall.position.set(6, 4, 0);\n    scene.add(rightWall);\n\n    // 햇살 창문 표현\n    const windowGeo = new THREE.PlaneGeometry(3, 4);\n    const windowMat = new THREE.MeshBasicMaterial({ color: 0xebf4fa });\n    const windowMesh = new THREE.Mesh(windowGeo, windowMat);\n    windowMesh.rotation.y = -Math.PI / 2;\n    windowMesh.position.set(5.98, 4.2, 0);\n    scene.add(windowMesh);\n}\n\nfunction buildFurniture() {\n    // 1. 빛나는 대형 벽걸이 십자가 (핵심 핫스팟)\n    const crossGroup = new THREE.Group();\n    const crossMat = new THREE.MeshStandardMaterial({ \n        color: 0xffd700, \n        metalness: 0.8, \n        roughness: 0.2, \n        emissive: 0xaa7c11,\n        emissiveIntensity: 0.3\n    });\n    \n    // 수직 기둥\n    const verticalBar = new THREE.Mesh(new THREE.BoxGeometry(0.3, 2.8, 0.15), crossMat);\n    verticalBar.position.y = 1.4;\n    crossGroup.add(verticalBar);\n\n    // 수평 기둥\n    const horizontalBar = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.3, 0.15), crossMat);\n    horizontalBar.position.y = 2.0;\n    crossGroup.add(horizontalBar);\n\n    crossGroup.position.set(0, 2.5, -5.85);\n    scene.add(crossGroup);\n\n    // 십자가 핫스팟 등록\n    registerInteractive(crossGroup, "cross", "십자가 묵상 & 오늘의 축복기도");\n\n    // 2. 목양실 메인 책상\n    const deskGroup = new THREE.Group();\n    const deskMat = new THREE.MeshStandardMaterial({ color: 0x2b1d0c, roughness: 0.5 });\n    \n    // 책상 상판\n    const deskTop = new THREE.Mesh(new THREE.BoxGeometry(3.2, 0.15, 1.6), deskMat);\n    deskTop.position.y = 1.4;\n    deskTop.castShadow = true;\n    deskGroup.add(deskTop);\n\n    // 책상 다리\n    const legGeo = new THREE.BoxGeometry(0.12, 1.4, 0.12);\n    [ [-1.5, -0.7], [1.5, -0.7], [-1.5, 0.7], [1.5, 0.7] ].forEach(([x, z]) => {\n        const leg = new THREE.Mesh(legGeo, deskMat);\n        leg.position.set(x, 0.7, z);\n        deskGroup.add(leg);\n    });\n\n    // 3. 책상 위 성경책 (핫스팟)\n    const bibleMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.4 });\n    const bible = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.08, 0.7), bibleMat);\n    bible.position.set(-0.8, 1.52, 0.2);\n    deskGroup.add(bible);\n    registerInteractive(bible, "bible", "청년 장교를 위한 성경 말씀");\n\n    // 성경책 위 금박 십자가\n    const bCrossMat = new THREE.MeshBasicMaterial({ color: 0xffd700 });\n    const bCross = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.02, 0.3), bCrossMat);\n    bCross.position.set(-0.8, 1.57, 0.2);\n    deskGroup.add(bCross);\n\n    // 4. 책상 위 노트북 & 램프\n    const laptopMat = new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.8 });\n    const laptop = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.04, 0.4), laptopMat);\n    laptop.position.set(0.4, 1.5, 0.1);\n    deskGroup.add(laptop);\n\n    deskGroup.position.set(0, 0, -2.5);\n    scene.add(deskGroup);\n\n    // 5. 상담 가죽 소파 (핫스팟)\n    const sofaGroup = new THREE.Group();\n    const sofaMat = new THREE.MeshStandardMaterial({ color: 0x5c4033, roughness: 0.7 });\n    \n    // 소파 바닥\n    const sofaBase = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.5, 1.0), sofaMat);\n    sofaBase.position.y = 0.4;\n    sofaGroup.add(sofaBase);\n\n    // 소파 등받이\n    const sofaBack = new THREE.Mesh(new THREE.BoxGeometry(2.4, 0.9, 0.3), sofaMat);\n    sofaBack.position.set(0, 0.9, -0.4);\n    sofaGroup.add(sofaBack);\n\n    sofaGroup.position.set(-3.2, 0, 1.5);\n    sofaGroup.rotation.y = Math.PI / 4;\n    scene.add(sofaGroup);\n    registerInteractive(sofaGroup, "sofa", "1:1 목양상담 예약");\n\n    // 6. 찬양 오디오 / 스피커 (핫스팟)\n    const audioMesh = new THREE.Mesh(\n        new THREE.BoxGeometry(0.6, 0.9, 0.5),\n        new THREE.MeshStandardMaterial({ color: 0x1f2937, metalness: 0.3 })\n    );\n    audioMesh.position.set(3.8, 0.45, 1.5);\n    scene.add(audioMesh);\n    registerInteractive(audioMesh, "audio", "은혜로운 찬양 BGM 재생");\n\n    // 7. 반짝이는 펄스 마커(Glow Marker) 추가\n    addGlowMarker(0, 4.0, -5.7, "십자가");\n    addGlowMarker(-0.8, 1.7, -2.3, "성경");\n    addGlowMarker(-3.2, 1.6, 1.5, "상담소파");\n    addGlowMarker(3.8, 1.2, 1.5, "찬양기");\n}\n\nfunction addGlowMarker(x, y, z, label) {\n    const geo = new THREE.SphereGeometry(0.12, 16, 16);\n    const mat = new THREE.MeshBasicMaterial({ color: 0xffd700, wireframe: true });\n    const marker = new THREE.Mesh(geo, mat);\n    marker.position.set(x, y, z);\n    scene.add(marker);\n\n    // 애니메이션을 위해 저장\n    interactiveObjects.push({ mesh: marker, type: \'glow\', baseY: y });\n}\n\nfunction registerInteractive(obj, type, name) {\n    obj.userData = { type, name };\n    interactiveObjects.push({ mesh: obj, type });\n}\n\nfunction onDocumentClick(event) {\n    const rect = renderer.domElement.getBoundingClientRect();\n    mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;\n    mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;\n\n    raycaster.setFromCamera(mouse, camera);\n    const intersects = raycaster.intersectObjects(scene.children, true);\n\n    if (intersects.length > 0) {\n        let hit = intersects[0].object;\n        while (hit && !hit.userData.type && hit.parent) {\n            hit = hit.parent;\n        }\n\n        if (hit && hit.userData.type) {\n            handleInteraction(hit.userData.type);\n        }\n    }\n}\n\nfunction handleInteraction(type) {\n    if (type === "cross") {\n        openModal("prayer-modal");\n    } else if (type === "bible") {\n        openModal("bible-modal");\n    } else if (type === "sofa") {\n        window.location.href = "/counseling";\n    } else if (type === "audio") {\n        toggleBgm();\n    }\n}\n\nfunction focusCamera(view) {\n    if (view === "all") {\n        gsapMoveCamera(0, 4.5, 9, 0, 2, 0);\n    } else if (view === "cross") {\n        gsapMoveCamera(0, 3.8, 2, 0, 3.8, -5.8);\n    } else if (view === "desk") {\n        gsapMoveCamera(0, 2.8, 0.5, 0, 1.5, -2.5);\n    } else if (view === "sofa") {\n        gsapMoveCamera(-2.5, 2.5, 4, -3.2, 1.0, 1.5);\n    }\n}\n\nfunction gsapMoveCamera(cx, cy, cz, tx, ty, tz) {\n    camera.position.set(cx, cy, cz);\n    controls.target.set(tx, ty, tz);\n    controls.update();\n}\n\nfunction onWindowResize() {\n    const container = document.getElementById("canvas-container");\n    if (!container) return;\n    camera.aspect = container.clientWidth / container.clientHeight;\n    camera.updateProjectionMatrix();\n    renderer.setSize(container.clientWidth, container.clientHeight);\n}\n\nfunction animate() {\n    requestAnimationFrame(animate);\n    controls.update();\n\n    // 마커 회전\n    const time = Date.now() * 0.003;\n    interactiveObjects.forEach(item => {\n        if (item.type === \'glow\') {\n            item.mesh.rotation.y += 0.02;\n            item.mesh.position.y = item.baseY + Math.sin(time) * 0.05;\n        }\n    });\n\n    renderer.render(scene, camera);\n}\n'}
